(561, 0, 'frFR', 'Qu’est ce qu’une "matrice souterraine" ?', ''),
(562, 0, 'frFR', 'Qui sont les Terrestres ?', ''),
(563, 0, 'frFR', 'Quelles sont les anomalies dont vous parliez ?', ''),
(564, 0, 'frFR', 'Que sont des "bases de construction résistantes" ?', ''),
(565, 0, 'frFR', 'Alors comme ça, les Terrestres étaient faits de roche ?', ''),
(566, 0, 'frFR', 'Est-ce qu’il y a autre chose que je devrais savoir à propos des Terrestres ?', ''),
(567, 0, 'frFR', 'Je crois comprendre maintenant quelles étaient les intentions des Créateurs quand ils conçurent les Terrestres. Quelles sont ces anomalies qui leur sont inhérentes et dont vous parliez plus tôt ?', ''),
(568, 0, 'frFR', 'Quels environnements stressants pourraient causer la déstabilisation des Terrestres ?', ''),
(569, 0, 'frFR', 'Que se passe-t-il quand les Terrestres sont déstabilisés ?', ''),
(570, 0, 'frFR', 'Les Troggs ?! Est-ce que les Troggs dont vous avez parlé sont les mêmes que ceux qui peuplent le monde aujourd’hui ?', ''),
(571, 0, 'frFR', 'Vous avez mentionné deux conséquences résultant de la déstabilisation des Terrestres. Quelle est la seconde ?', ''),
(572, 0, 'frFR', 'Les nains !!! Maintenant vous me dites que les nains descendent des Terrestres ?!', ''),
(573, 0, 'frFR', 'Les nains sont les mêmes aujourd’hui qu’à cette époque, oui ? Conservent-ils encore d’autres liens avec les Terrestres ?', ''),
(574, 0, 'frFR', 'Qui sont les Créateurs ?', ''),
(575, 0, 'frFR', 'Voilà de quoi méditer longuement.', ''),
(576, 0, 'frFR', 'Je vais accéder aux disques, maintenant.', ''),
(581, 0, 'frFR', 'Entraînez-moi.', ''),
