(5708, 0, 'frFR', 'Comment ça, je suis le nouveau roi ? Qu’est-ce que vous racontez ?', ''),
(5708, 1, 'frFR', 'Sbires ? Tribut ?', ''),
(5709, 0, 'frFR', 'Un jeu ? Vous êtes dingue ?', ''),
(5710, 0, 'frFR', 'Pourquoi espèce de petit…', ''),
(5711, 0, 'frFR', 'Écoute-moi bien, diablotin. Je t’attraperai. Et quand je te tiendrai…', ''),
(5712, 0, 'frFR', 'À mort !', ''),
(5713, 0, 'frFR', 'Préparez-vous à rencontrer votre créateur.', ''),
(5715, 0, 'frFR', 'C’est bon d’être le roi ! Maintenant, revenons à ce dont vous parliez juste avant…', ''),
(5723, 0, 'frFR', 'Une histoire très triste. Merci, esprit.', ''),
(5724, 0, 'frFR', 'Nous vivons dans une tragédie sans fin.', ''),
(5725, 0, 'frFR', 'Il va falloir que je tue des trucs, pas vrai ?', ''),
(5726, 0, 'frFR', 'Fascinant. Continuez, s’il vous plaît.', ''),
(5727, 0, 'frFR', 'Continuez, je vous prie.', ''),
(5728, 0, 'frFR', 'Je ne sais presque rien des Bien-nés et rien des Shen’dralar.', ''),
(5729, 0, 'frFR', 'Qu’est-il arrivé ici, esprit ?', ''),
(5733, 0, 'frFR', 'Ouais, t’es un vrai génie. Tu te crois vraiment brillant, pas vrai, Slip’kik ?', ''),
(5734, 0, 'frFR', 'Bon, maintenant que je suis le roi… qu’avez-vous pour moi ?', ''),
(5735, 0, 'frFR', 'Appelez-moi “Patron”. Qu’avez-vous pour moi ?', ''),
(5738, 0, 'frFR', 'Heu… c’est comme ça que je les ai trouvés. Je voulais montrer au roi qu’ils étaient dangereux ! Oh, capitaine… j’ai entendu le garde Fengus vous traiter de gros incapable dont la mère était un Gnoll.', ''),
(5739, 0, 'frFR', 'Heu, nous les avons capturés dehors, et je les amène au roi pour qu’il les punisse.', ''),
(5740, 0, 'frFR', 'Très bien… montrez-moi le tribut !', ''),
(5743, 0, 'frFR', 'Pleure cette terrible perte.', ''),
(5743, 1, 'frFR', 'Pleure cette terrible perte.', ''),
(5744, 0, 'frFR', 'On dirait une tâche digne du nouveau roi !', ''),
(5749, 0, 'frFR', '<Vous copiez le schéma dans votre carnet d’ingénierie.>', ''),
(5750, 0, 'frFR', 'Transportez-moi au Cœur du Magma, Lothos.', ''),
(5764, 0, 'frFR', 'Que voulez-vous dire ? Quelle coïncidence, Rabine ?', ''),
(5765, 0, 'frFR', 'Le Fruit de Fertilité ?', ''),
(5767, 0, 'frFR', 'Que voulez-vous que je fasse, Rabine ?', ''),
(5768, 0, 'frFR', 'Que se passerait-il si le Fruit de Fertilité – ou la Gangrevigne – était entièrement corrompu ?', ''),
(5769, 0, 'frFR', 'Mais quelque chose a mal tourné, non ?', ''),
(5818, 0, 'frFR', 'Gorzeeki, j’aimerais faire un ou deux achats.', ''),
(5848, 1, 'frFR', 'J''ai besoin d''un nouveau sifflet d''orphelin orc.', ''),
(5849, 1, 'frFR', 'J''ai besoin d''un nouveau sifflet d''orphelin humain.', ''),
(5853, 0, 'frFR', 'Entraînez-moi.', ''),
(5854, 0, 'frFR', 'Entraînez-moi.', ''),
(5855, 0, 'frFR', 'Entraînez-moi.', ''),
(5856, 0, 'frFR', 'Entraînez-moi.', ''),
(5962, 0, 'frFR', 'J’aimerais jeter un œil à vos marchandises.', ''),
(5963, 0, 'frFR', 'Allons-y ! On s''charge de Maltorius et Arkkus !', ''),
(5967, 0, 'frFR', 'Je dois voyager.', ''),
(5968, 0, 'frFR', 'Je dois voyager.', ''),
(5981, 0, 'frFR', 'Je n’ai commis aucune faute.', ''),
(6001, 0, 'frFR', 'Posez la main sur la sphère.', ''),
(6021, 0, 'frFR', 'Je ne peux pas, Vaelastrasz ! Il doit sûrement y avoir un moyen de vous guérir !', ''),
(6023, 0, 'frFR', 'Je dois voyager.', ''),
(6045, 0, 'frFR', 'Faites.', ''),
(6046, 0, 'frFR', 'Vous avez perdu la tête, Nefarius. Vous parlez en énigmes.', ''),
(6059, 0, 'frFR', 'Faire de cette auberge votre foyer.', ''),
(6059, 1, 'frFR', 'Laissez-moi jeter un coup d’œil sur vos marchandises.', ''),
(6083, 0, 'frFR', 'Je voudrais vous acheter quelque chose.', ''),
(6085, 0, 'frFR', 'Je voudrais vous acheter quelque chose.', ''),
(6086, 0, 'frFR', 'Je voudrais vous acheter quelque chose.', ''),
(6087, 0, 'frFR', 'Je voudrais vous acheter quelque chose.', ''),
(6087, 1, 'frFR', 'Que pouvez-vous m’apprendre ?', ''),
(6101, 0, 'frFR', 'Vaelastrasz, non !!!', ''),
(6162, 0, 'frFR', 'Je dois voyager.', ''),
(6182, 0, 'frFR', 'Silas, pourquoi presque tout est-il gratuit à la foire ? Comment faites-vous du profit ?', ''),
(6183, 0, 'frFR', 'Laissez-moi jeter un coup d’œil sur vos marchandises.', ''),
(6185, 0, 'frFR', 'Cet homme est un voleur et un menteur. Je l’exécute sur-le-champ, comme le voudrait mon seigneur.', ''),
(6185, 1, 'frFR', 'Cet homme a violé la loi que j’ai juré de servir. Je le remets à mon seigneur pour qu’il soit châtié.', ''),
(6185, 2, 'frFR', 'Je confisque le maïs volé, je l’avertis que le vol est le plus court chemin vers la ruine et la mort, puis je le laisse retrouver sa famille.', ''),
(6185, 3, 'frFR', 'Je donne à l’homme assez de maïs pour nourrir sa famille pendant deux jours, et je lui conseille de quitter le pays.', ''),
(6186, 0, 'frFR', 'Je suis prêt à découvrir mon avenir.', ''),
(6187, 0, 'frFR', 'Je l’exécute selon les ordres de mon seigneur et fais en sorte qu’il endure de grandes souffrances avant de mourir en punition de ses crimes contre mon peuple.', ''),
(6187, 1, 'frFR', 'Je l’exécute selon les ordres de mon seigneur, mais de la façon la moins douloureuse possible. Justice doit être faite, mais je sais faire preuve de compassion.', ''),
(6187, 2, 'frFR', 'Au péril de ma vie, je le libère pour lui permettre de prouver son innocence. Si cela m’est possible, je fais tout pour l’aider.', ''),
(6202, 0, 'frFR', 'Laissez-moi jeter un coup d’œil sur vos marchandises.', ''),
(6202, 1, 'frFR', 'Parlez-moi des cartes de Sombrelune.', ''),
(6207, 0, 'frFR', 'Parlez-moi du jeu des Bêtes.', ''),
(6207, 1, 'frFR', 'Parlez-moi du jeu des Portails.', ''),
(6207, 2, 'frFR', 'Parlez-moi du jeu des Élémentaires.', ''),
(6207, 3, 'frFR', 'Parlez-moi du jeu des Seigneurs de guerre.', ''),
(6207, 4, 'frFR', 'Parlez-moi du jeu des Furies.', ''),
(6207, 5, 'frFR', 'Parlez-moi du jeu de la Démence.', ''),
(6207, 6, 'frFR', 'Parlez-moi du jeu des Bénédictions.', ''),
(6207, 7, 'frFR', 'Parlez-moi du jeu des Tempêtes.', ''),
(6207, 8, 'frFR', 'Est-ce qu’il existe d’autres suites ?', ''),
(6208, 0, 'frFR', 'J’interpelle le dirigeant au sujet de son vil comportement et défends l’honneur de mon seigneur, mettant en péril nos relations diplomatiques.', ''),
(6208, 1, 'frFR', 'Je fais mine de ne pas avoir entendu l’insulte tout en faisant planer le doute, espérant laisser le dirigeant dans la crainte d’avoir commis un impair. J’informe mon seigneur de l’insulte à mon retour.', ''),
(6208, 2, 'frFR', 'Je fais comme si je n’avais pas entendu. Je ne dirai rien à mon seigneur, car je veux assurer la paix à tout prix. Ce n’est qu’une insulte, pas une déclaration de guerre.', ''),
(6209, 0, 'frFR', 'Je m’opposerais ouvertement à ce que mon frère rejoigne l’ordre, entraînant une rupture durable entre nous deux. Il représenterait un danger pour lui-même et ses compagnons, espérer qu’il s’améliore avec le temps serait prendre un trop grand risque.', ''),
(6209, 1, 'frFR', 'Je demanderais à ce que mon frère soit accepté, nuisant peut-être à la sécurité de l’ordre. Je chercherais à l’aider au sein de l’ordre et j’aurais confiance en sa capacité à s’adapter et apprendre.', ''),
(6209, 2, 'frFR', 'Je chercherais par quelque moyen discret à empêcher mon frère de rejoindre l’ordre. Je peux m’opposer à sa présence dans l’ordre sans qu’il n’en sache rien, maintenant ainsi nos liens familiaux.', ''),
(6210, 0, 'frFR', 'Le choix suivant vous attend.$B$BVous avez vaincu $gseul:seule; une bête terrible qui causait des ravages dans les campagnes et pris son oreille en guise de trophée. Vous apprenez plus tard que votre seigneur avait offert une récompense pour la mort de la bête, et qu’un chevalier bon mais pauvre, dont vous savez qu’il cherche à nourrir une famille avec des revenus très modestes, affirme avoir lui-même tué la bête. Vous n’avez pas vraiment besoin d’argent, mais vous savez que le chevalier pauvre ment pour son profit personnel.$B$BFaites votre choix.', ''),
(6210, 1, 'frFR', 'Je montrerais à mon seigneur l’oreille de la bête et revendiquerais sa mort : après tout, c’est moi qui l’ai tuée. Je proposerais ensuite une partie de la récompense au chevalier pauvre pour aider sa famille.', ''),
(6210, 2, 'frFR', 'Je ne dirais rien et laisserais le chevalier recevoir la récompense pour subvenir aux besoins de sa famille.', ''),
(6211, 0, 'frFR', 'J’aimerais beaucoup recevoir une de ces prédictions écrites dont vous avez parlé ! J’ai de la place dans mon inventaire.', ''),
(6213, 1, 'frFR', 'Vous dites que la foire de Sombrelune est déjà arrivée ? Où se trouve-t-elle ?', ''),
(6214, 0, 'frFR', 'Quand la foire de Sombrelune arrivera, où s’installera-t-elle ?', ''),
(6225, 0, 'frFR', 'Comment on joue à ce jeu de tir ?', ''),
(6225, 1, 'frFR', 'Je suis prêt à tirer ! |cFF0008E8(Jeton de Sombrelune)|r', ''),
(6230, 0, 'frFR', 'Montrez-moi les boissons.', ''),
(6231, 0, 'frFR', 'Vous voulez dire que vous vendez des grenouilles ?', ''),
(6233, 0, 'frFR', 'Qu’avez-vous à vendre ?', ''),
(6234, 0, 'frFR', 'Mmmmm… à manger.', ''),
(6321, 0, 'frFR', 'Jin''rokh, j''ai besoin d''aide pour récupérer une pièce de ma tenue de libre penseur.', ''),
(6321, 1, 'frFR', 'Jin''rokh, j''ai besoin d''aide pour récupérer une pièce de ma tenue de vindicateur.', ''),
(6322, 0, 'frFR', 'Al''tabim, j''ai besoin d''aide pour récupérer une pièce de ma tenue de confesseur.', ''),
