(6322, 2, 'frFR', 'Al''tabim, j''ai besoin d''aide pour récupérer une pièce de ma tenue d''illusionniste.', ''),
(6341, 0, 'frFR', 'Maywiki, j''ai besoin d''aide pour récupérer une pièce de ma tenue d''augure.', ''),
(6341, 1, 'frFR', 'Maywiki, j''ai besoin d''aide pour récupérer une pièce de ma tenue d''haruspice.', ''),
