(6533, 0, 'frFR', 'Bonjour, Frankal. J’ai entendu dire que vous aviez peut-être des informations sur les faits et gestes de dame Natalia Mar’alith.', ''),
(6534, 0, 'frFR', 'Bonjour, Rutgar. Le commandant m’envoie enquêter sur la disparition de sa femme.', ''),
(6535, 0, 'frFR', 'Barbouillez-moi la figure de cendres, comme pour des peintures de guerre !', ''),
(6539, 16, 'frFR', 'Oui, Anachronos, montrez-moi votre vision de l’avenir.', ''),
(6540, 0, 'frFR', 'Je ne suis pas un de vos sectateurs, espèce de monstre ! Venez à moi et préparez-vous à être anéanti !', ''),
(6542, 0, 'frFR', 'Écoutez, infâme duc ! Je ne suis pas un de vos valets du Marteau du crépuscule ! Je suis ici pour vous défier ! Venez ! Venez, et préparez-vous à mourir…', ''),
(6543, 0, 'frFR', 'Le jour du jugement est arrivé, démon ! Je vous demande de m’affronter !', ''),
(6545, 0, 'frFR', 'Je reviendrai dès que j’aurai tiré tout ça au clair.', ''),
(6546, 0, 'frFR', 'Possédée par quoi ?', ''),
(6547, 0, 'frFR', 'Comment ça, craqué ?', ''),
(6548, 0, 'frFR', 'Quoi donc ?', ''),
(6549, 0, 'frFR', 'Natalia ?', ''),
(6550, 0, 'frFR', 'Que s’est-il passé ensuite ?', ''),
(6551, 0, 'frFR', 'Ça a l’air dangereux.', ''),
(6552, 0, 'frFR', 'Merci pour ces informations, Frankal.', ''),
(6553, 0, 'frFR', 'C’est une sacrée histoire ! Donc, elle a filé dans Ruche’Regal, et vous ne l’avez pas revue ?', ''),
(6554, 0, 'frFR', 'Et alors ?', ''),
(6555, 0, 'frFR', 'À propos, je voulais que vous me parliez du singe.', ''),
(6556, 0, 'frFR', 'Ne me dites pas que vous avez eu du mal à venir à bout d’une simple prêtresse elfe de la nuit.', ''),
(6557, 0, 'frFR', 'C''est bizarre.', ''),
