(7396, 0, 'frFR', 'Je voudrais regarder vos articles.', ''),
(7399, 0, 'frFR', 'Donnez-moi une lettre de l''amiral.', ''),
(7401, 0, 'frFR', 'Nous avons beaucoup de choses en commun, Elfe de la nuit. Je me demande si le destin ne nous a pas réunis. Laissez-moi vous aider, Cowlen. Laissez mon peuple vous aider. Nous redresserons les torts. J’en fais le serment.', ''),
(7402, 0, 'frFR', 'J’ai peur que mon peuple ne soit responsable de cette destruction. Nous sommes des réfugiés, chassés de nos foyers par la Légion ardente. Notre dernière fuite a causé cette tragédie. Notre vaisseau s’est écrasé, et ce débris en fait partie.', ''),
(7403, 0, 'frFR', 'Je ne suis pas venu vous tuer, Elfe de la nuit. Et les dieux ne sont pour rien dans tout ceci…', ''),
(7410, 0, 'frFR', 'J’aimerais jeter un œil à vos marchandises.', ''),
(7413, 0, 'frFR', 'Contrôle de fantassin humain', ''),
(7415, 0, 'frFR', 'Je suis prêt pour le vol vers l’Exodar.', ''),
(7421, 0, 'frFR', 'Je ne suis pas un comédien.', ''),
(7421, 2, 'frFR', 'Les doigts dans le nez !', ''),
(7422, 0, 'frFR', 'D’accord, je veux bien essayer, alors.', ''),
(7426, 0, 'frFR', 'C''est terminé, l''Étincelle. L''amiral sait que c''est toi qui as trahi l''Alliance. Maintenant soit tu coopères avec moi et tu me dis tout ce que tu sais, soit on va régler ça aux bourre-pifs.', ''),
(7428, 0, 'frFR', 'Je voudrais jeter un œil sur vos marchandises, Ergh.', ''),
(7429, 0, 'frFR', 'Accepteriez-vous de m''apprendre le dépeçage, Gurf ?', ''),
(7430, 0, 'frFR', 'Je souhaite apprendre le travail du cuir, Moordo. Pouvez-vous me l’enseigner ?', ''),
(7435, 0, 'frFR', 'J’ai besoin de vos compétences de forgeron, Koren.', ''),
