(7471, 1, 'frFR', 'Je souhaite jeter un coup d’œil à vos marchandises.', ''),
(7475, 0, 'frFR', 'Alors pourquoi êtes-vous toujours ici ?', ''),
(7476, 0, 'frFR', 'Jusqu’à quoi ?', ''),
(7477, 0, 'frFR', 'Qui est Ysera et en quoi étiez-vous béni ?', ''),
