(7482, 0, 'frFR', 'Écoutez-moi, Humain. Votre situation m’indiffère, mais vous avez quelque chose dont j’ai besoin. Dites-moi où je peux trouver les lingots de forge-sang.', ''),
(7484, 0, 'frFR', 'Comment puis-je former une guilde ?', ''),
(7484, 1, 'frFR', 'Je désire créer une bannière de guilde.', ''),
