(7493, 0, 'frFR', '<Tournez la page.>', ''),
(7494, 0, 'frFR', 'Je veux devenir forgeron.', ''),
(7495, 0, 'frFR', 'Gardienne Leesa’oh, pourquoi êtes-vous ici ?', ''),
(7497, 0, 'frFR', 'Faire de cette auberge votre foyer.', ''),
(7497, 1, 'frFR', 'Je voudrais regarder vos articles.', ''),
(7499, 0, 'frFR', 'Nous allons vous faire sortir de là, Thrall. On y va !', ''),
(7499, 1, 'frFR', 'Nous allons vous faire sortir de là, Thrall. On y va !', ''),
(7502, 0, 'frFR', 'Oui, continuez s’il vous plaît.', ''),
(7503, 0, 'frFR', 'Volontiers, si ça ne vous dérange pas.', ''),
(7504, 0, 'frFR', 'Continuez, Nobundo, s’il vous plaît.', ''),
(7505, 0, 'frFR', 'Qu’est-ce qu’elle vous a dit ?', ''),
(7506, 0, 'frFR', 'C’était quoi, ça ?', ''),
(7507, 0, 'frFR', 'Qu’avez-vous fait ?', ''),
(7508, 0, 'frFR', 'Continuez, s’il vous plaît.', ''),
(7517, 0, 'frFR', 'Veuillez m’apprendre.', ''),
(7520, 0, 'frFR', 'D’accord, Morsure, je vais te laisser sortir.', ''),
(7522, 0, 'frFR', 'Enseignez-moi la voie des Esprits.', ''),
(7522, 1, 'frFR', 'Je voudrais oublier mes talents.', ''),
(7522, 2, 'frFR', 'Je voudrais en savoir plus sur la double spécialisation de talents.', ''),
(7524, 0, 'frFR', 'Je voudrais regarder vos articles.', ''),
(7524, 1, 'frFR', 'Entraînez-moi.', ''),
(7531, 0, 'frFR', 'Je suis un prisonnier, qu’est-ce que vous croyez ? Ces racailles de Draeneï m’ont capturé alors que je sortais du portail du soleil. Ils ont tué les contrôleurs du portail et détruit le passage. Le roi-soleil sera très mécontent quand il apprendra ce qui s’est passé.', ''),
(7533, 0, 'frFR', 'C’est ce que j’ai dit, et vous m’avez cru. Merci pour les informations, Elfe de sang. Vous nous avez aidés bien plus que vous ne le croyez…', ''),
(7534, 0, 'frFR', 'La bobine vectorielle est énorme. J’espère que nous avons plus d’une abomination pour garder ses nombreux points faibles.', ''),
(7535, 0, 'frFR', 'Sironas est une érédar… c’est évident.', ''),
(7536, 0, 'frFR', 'Incroyable. Comment Sironas s’y est-elle prise ?', ''),
(7537, 0, 'frFR', 'Ah oui, Sironas. J’avais presque oublié que Sironas était ici. J’ai servi sous ses ordres en Outreterre. Mais je n’avais pas entendu parler de cette abomination… Ces maudits Draeneï m’ont capturé avant même que je me sois complètement matérialisé sur ce monde.', ''),
(7540, 0, 'frFR', 'Naturaliste, veuillez m’offrir votre bénédiction.', ''),
(7552, 0, 'frFR', 'Mes compagnons et moi sommes à vos côtés, dame Portvaillant.', ''),
(7552, 1, 'frFR', 'Nous sommes prêts à affronter tout ce qu’Archimonde pourra mettre sur notre chemin, dame Portvaillant.', ''),
(7552, 2, 'frFR', 'À notre prochaine rencontre, dame Portvaillant.', ''),
(7557, 0, 'frFR', 'Parlez-moi des Défenseurs.', ''),
(7559, 0, 'frFR', 'Accorde-moi ta marque, sage ancien.', ''),
(7560, 0, 'frFR', 'Accorde-moi ta marque, sage ancien.', ''),
(7566, 0, 'frFR', 'Je brûle du désir de me perfectionner dans les arts des démonistes.', ''),
(7566, 1, 'frFR', 'Je voudrais oublier mes talents.', ''),
(7566, 2, 'frFR', 'Je voudrais en savoir plus sur la double spécialisation de talents.', ''),
(7567, 0, 'frFR', 'Je cherche une formation de druide.', ''),
(7567, 1, 'frFR', 'Je voudrais oublier mes talents.', ''),
(7567, 2, 'frFR', 'Je voudrais en savoir plus sur la double spécialisation de talents.', ''),
(7579, 0, 'frFR', 'Hemet Nesingwary ? Qu’est-ce que vous faites en Outreterre ?', ''),
(7581, 0, 'frFR', 'Nous n’avons rien à craindre.', ''),
(7581, 1, 'frFR', 'Je suis avec vous, Thrall.', ''),
(7581, 2, 'frFR', 'À notre prochaine rencontre, Thrall.', ''),
(7582, 0, 'frFR', 'Je vous salue, ancien. Il est temps que votre peuple cesse de se montrer hostile envers les Draeneï et leurs alliés.', ''),
(7583, 0, 'frFR', 'Je ne désirais pas vous tromper, ancien. Les Draeneï de Telredor souhaitaient juste adopter une approche qui vous était familière.', ''),
(7585, 0, 'frFR', 'Je le leur dirai. Adieu, ancien.', ''),
(7588, 0, 'frFR', 'Montrez-moi vos marchandises, Maktu.', ''),
(7589, 0, 'frFR', 'J’aimerais jeter un œil à vos marchandises.', ''),
(7590, 0, 'frFR', 'Laissez-moi regarder vos composants et vos poisons.', ''),
(7590, 1, 'frFR', 'Un spécialiste, hein ? Quel genre de spécialiste ?', ''),
(7593, 0, 'frFR', 'Archimage Cedric, je cherche un morceau de disque qu''Antonidas vous a confié. L''auriez-vous par hasard ?', ''),
(7596, 0, 'frFR', 'Votre nom n’est jamais évoqué qu’à demi-mot, mage. Qui êtes-vous ?', ''),
