(7668, 0, 'frFR', 'À l''ouest.', ''),
(7668, 1, 'frFR', 'À l''est.', ''),
(7669, 0, 'frFR', 'J’ai besoin de réponses, l’ogre !', ''),
(7671, 0, 'frFR', 'Cela veut dire que c''est la guerre, Gros-tas ! La guerre !', ''),
(7672, 0, 'frFR', 'Et tu penses que tu peux manger tout ce que tu veux ? Apparemment, tu essayes de manger les Roués de Telaar.', ''),
(7673, 0, 'frFR', 'Pourquoi les Rochepoings sont-ils si loin de chez eux ? Tu sais que c’est un territoire Kurenaï.', ''),
(7675, 0, 'frFR', 'J''ai tué beaucoup de vos ogres, Lantresor. Je n''ai pas peur.', ''),
(7676, 0, 'frFR', 'Que devrais-je faire ?', ''),
(7677, 0, 'frFR', 'Alors nous vous combattrons jusqu''à la mort, Lantresor. Nous ne resterons pas les bras croisés pendant que vous pillez nos villes et tuez notre peuple.', ''),
(7678, 0, 'frFR', 'Mon peuple demande que vous éloigniez vos Ogres rochepoings et que vous cessiez toutes vos attaques sur notre territoire. En échange, nous retirerons aussi nos forces.', ''),
(7679, 0, 'frFR', 'Mes excuses. Je ne voulais pas vous offenser. Je suis ici de la part de mon peuple.', ''),
(7680, 0, 'frFR', 'J’ai entendu parler de ceux de votre sorte, mais je pensais pas voir un jour un demi-sang.', ''),
(7681, 0, 'frFR', 'Et la seconde moitié ?', ''),
(7682, 0, 'frFR', 'Comment le saurais-je ? Vous ressemblez à un Orc.', ''),
(7690, 0, 'frFR', 'Entraînez-moi.', ''),
(7691, 0, 'frFR', 'Entraînez-moi.', ''),
(7692, 0, 'frFR', 'Arblos, je sais que la vérité est en vous, d''une manière ou d''une autre. Dites-moi ce que c''est.', ''),
(7704, 0, 'frFR', 'Empoor, vous allez me dire ce que je veux savoir, sinon...', ''),
(7706, 0, 'frFR', 'Je vous serais reconnaissant de m’apporter votre aide, prêtresse.', ''),
(7712, 0, 'frFR', 'Je voudrais regarder vos articles.', ''),
(7713, 0, 'frFR', 'Laissez-moi jeter un coup d’œil sur vos marchandises.', ''),
(7715, 0, 'frFR', 'Des camps de forge ?', ''),
(7716, 0, 'frFR', 'Comment les voyez-vous maintenant ?', ''),
(7717, 0, 'frFR', 'Et maintenant ?', ''),
(7718, 0, 'frFR', 'La légion ?', ''),
(7719, 0, 'frFR', 'Je vois de l’acier tordu et je sens l’odeur de la terre brisée.', ''),
(7719, 1, 'frFR', 'Parlez-moi du terrain d’entraînement pour chasseur de démons des ruines de Karabor.', ''),
(7722, 1, 'frFR', 'J’ai des marques à échanger !', ''),
(7724, 1, 'frFR', 'J’ai des marques à échanger !', ''),
(7725, 0, 'frFR', 'Altruis m''a envoyé. Il m''a dit que vous pouviez m''aider.', ''),
(7726, 0, 'frFR', 'Tenez le coup ! Quel est le problème avec le marécage de Zangar ?', ''),
(7727, 0, 'frFR', 'Je n’ai pas de temps à perdre avec ces bêtises ! Gardien, que s’est-il passé ?!', ''),
(7729, 0, 'frFR', 'C’est Sal’salabim qui m’envoie, pour récupérer l’or que tu lui dois. Paye, ou tu vas souffrir !', ''),
(7730, 0, 'frFR', 'C’est Sal’salabim qui m’envoie, pour récupérer l’or que tu lui dois. Paye, ou tu vas souffrir !', ''),
(7731, 0, 'frFR', 'Il veut ses « ors ». Paye, ou meurs… encore une fois…', ''),
(7732, 0, 'frFR', 'C’est Sal’salabim qui m’envoie, pour récupérer l’or que tu lui dois. Paye, ou tu vas souffrir !', ''),
(7735, 0, 'frFR', 'Que sont les Sha’tar?', ''),
(7735, 1, 'frFR', 'Shattrath n’est pas une ville draeneï ? Pourquoi permettez-vous à d’autres peuples de vivre ici ?', ''),
(7742, 0, 'frFR', 'Vous vous souvenez quand nous avons contraint l’Œil omnivoyant à espionner le Conseil des ombres ?', ''),
(7757, 0, 'frFR', 'Qu’est-ce que vous bricolez ?', ''),
(7759, 0, 'frFR', 'Que faites-vous ici ?', ''),
(7760, 0, 'frFR', 'Conseiller, quelles sont les dernières nouvelles ?', ''),
(7762, 0, 'frFR', 'Y a-t-il quoi que ce soit que je puisse faire pour vous, grande-mère ?', ''),
(7763, 0, 'frFR', 'Quel est ce devoir ?', ''),
(7764, 0, 'frFR', 'Partir ? Comment pouvez-vous décider de partir ?', ''),
(7765, 0, 'frFR', 'Que peut-on faire ? J’ai essayé de bien des manières. J’ai fait de mon mieux pour aider les gens de Nagrand. Chaque fois que j’ai approché Garrosh, il m’a rejeté.', ''),
(7766, 0, 'frFR', 'Vous y croyez ?', ''),
(7767, 0, 'frFR', 'Vous avez élevé tous les Orcs qui sont ici, grande-mère ?', ''),
(7768, 0, 'frFR', 'Je vous salue, grande-mère. Garrosh m’a dit que vous souhaitiez me parler.', ''),
(7768, 1, 'frFR', 'Garrosh ne peut plus être sauvé, grande-mère. J’ai bien peur, en aidant les Mag’har, d’avoir convaincu Garrosh qu’il n’est pas digne d’être chef.', ''),
(7769, 0, 'frFR', 'J’ai besoin d’un paquet de bombes incendiaires.', ''),
(7770, 0, 'frFR', 'En fait, j’aimerais vous poser quelques questions au sujet de votre grand-père.', ''),
(7772, 0, 'frFR', 'Éclaireur Neftis, il me faut un autre déguisement.', ''),
