(7829, 0, 'frFR', 'La situation est assez compliquée, Thrall. Il vaudrait mieux que vous filiez vers les montagnes dès maintenant, avant que d’autres hommes de Landenoire ne se montrent. Nous veillerons à la sécurité de Taretha.', ''),
