(7978, 0, 'frFR', 'Grande-mère, je n’avais jamais eu cet honneur. Durotan mourut bien avant mon époque, mais ses exploits héroïques sont connus de tous sur mon monde. Les Orcs d’Azeroth habitent une région appelée Durotar, en hommage à votre fils. Et… <Vous faites une pause pour reprendre votre souffle et réfléchir à ce que vous allez dire à la grande-mère.>', ''),
