(9280, 0, 'frFR', '<Fouiller le cadavre à la recherche du totem d''Issliruk.>', ''),
(9283, 0, 'frFR', 'Qui est Malygos ?', ''),
(9285, 0, 'frFR', 'Faites-moi un rapport sur la situation, capitaine.', ''),
(9286, 2, 'frFR', 'Où en sont les portes du Puits de soleil ?', ''),
(9287, 0, 'frFR', 'Quel était le problème ?', ''),
(9288, 0, 'frFR', 'Pourquoi n’ont-ils pas continué ?', ''),
(9289, 0, 'frFR', 'Votre opinion m’intéresse.', ''),
(9297, 0, 'frFR', 'Vous n’êtes pas seul ici ?', ''),
(9297, 1, 'frFR', 'En quoi une femme mortelle intéresserait-elle Kil’jaeden ?', ''),
(9299, 1, 'frFR', 'Faire de cette auberge votre foyer.', ''),
(9299, 3, 'frFR', 'Je veux vous acheter quelque chose.', ''),
(9301, 0, 'frFR', 'Venez, Budd. Il est l’heure d’aller jouer avec les Trolls de glace !', ''),
(9302, 0, 'frFR', 'Ne vous en faites plus, taunka. La Horde vous sauvera et vous protégera, vous et votre peuple. Mais d’abord, vous devez jurer allégeance au chef de guerre, en prêtant le serment de sang de la Horde.', ''),
(9303, 0, 'frFR', 'Pour la Horde !\n\nChoisissez-vous des armes dans les caisses que vous voyez là, et allez vous présenter au Marteau d’Agmar, à l’est d’ici. Votre première épreuve en tant que membre de la Horde sera de survivre au voyage.\n\nLok’tar ogar !', ''),
(9304, 0, 'frFR', 'Alors, répétez après moi : « Lok’tar ogar ! La victoire ou la mort. Ces mots me lient à la Horde, car ils sont pour tout guerrier de la Horde la vérité la plus profonde et la plus sacrée qui soit.\n\nJe donne librement ma chair et mon sang au chef de guerre. Je suis l’instrument de la volonté du chef de guerre. Je suis une arme que brandit à sa guise le chef de guerre.\n\nDès cet instant et jusqu’à la fin de mes jours, je vis et je meurs... pour la Horde ! »', ''),
(9305, 0, 'frFR', 'Oui, taunka. La vengeance est un droit fondamental de tous les membres de la Horde.', ''),
(9307, 0, 'frFR', 'J’ai autre chose à vous demander.', ''),
(9335, 0, 'frFR', 'Mmm… La grenouille dit que vous êtes un traître, « moussaillon ».', ''),
(9352, 0, 'frFR', 'Étouffez le feu de joie de l’Alliance !', ''),
(9353, 0, 'frFR', 'Étouffez le feu de joie de la Horde !', ''),
(9354, 0, 'frFR', 'Étouffez le feu de joie de l’Alliance !', ''),
(9355, 0, 'frFR', 'Étouffez le feu de joie de la Horde !', ''),
