(9413, 0, 'frFR', 'Étouffez le feu de joie de l’Alliance !', ''),
(9415, 0, 'frFR', 'Donnez-moi accès au téléporteur, je suis prêt à y aller !', ''),
(9416, 0, 'frFR', 'J’aimerais encore un peu de ce bon grog, Mack.', ''),
(9418, 0, 'frFR', 'Allons-y, Thassarian. C''est maintenant ou jamais.', ''),
(9422, 0, 'frFR', 'On dirait bien que j’ai égaré votre télécommande de déchiqueteur. C’est ballot. En auriez-vous une autre ?', ''),
(9426, 0, 'frFR', 'Arracher l''œil de l''idole.', ''),
(9427, 2, 'frFR', 'Faire de cette auberge votre foyer.', ''),
(9427, 3, 'frFR', 'Laissez-moi jeter un coup d’œil sur vos marchandises.', ''),
(9429, 0, 'frFR', 'Je vais vous montrer ! Donnez-moi ce parachute d’entraînement !', ''),
(9434, 0, 'frFR', 'Faites descendre ce wyrm de givre au sol et je l''achèverai.', ''),
(9437, 0, 'frFR', 'J’aimerais utiliser l’écurie.', ''),
(9453, 0, 'frFR', 'Laissez-moi jeter un coup d’œil sur vos marchandises.', ''),
(9454, 0, 'frFR', 'Actionner les leviers de la console.', ''),
(9455, 0, 'frFR', 'Régisseur, j’aimerais chevaucher un drake jusqu’à la chambre de la reine au sommet du temple.', ''),
(9455, 1, 'frFR', 'Pouvez-vous me prêter un drake pour m''emmener voir le seigneur Afrasastrasz au milieu du temple ?', ''),
(9455, 2, 'frFR', 'Avez-vous entendu parler d’un grand dragon qui aurait péri sur un glacier au nord de la couronne ?', ''),
(9456, 0, 'frFR', 'Je dois retourner dans le monde des ombres, Koltira. Renvoyez-moi là-bas.', ''),
(9457, 0, 'frFR', 'Oui, s’il vous plaît, je voudrais retourner au rez-de-chaussée du temple.', ''),
(9457, 1, 'frFR', 'Je voudrais aller voir le seigneur Afrasastrasz au milieu du temple.', ''),
(9459, 0, 'frFR', 'Entraînez-moi.', ''),
