(9537, 0, 'frFR', 'On dirait qu’un des sectateurs a malencontreusement trébuché sur mon arme… Quel maladroit. Puis-je avoir un nouveau déguisement ? Je vous promets de faire plus attention cette fois-ci.', ''),
