(9838, 0, 'frFR', 'Je désire créer une bannière de guilde.', ''),
(9838, 1, 'frFR', 'Comment puis-je former une guilde ?', ''),
(9839, 0, 'frFR', 'Koltira… Ça va peut-être vous sembler loufoque, mais je n’arrête pas de voir le fantôme d’un gamin. Matthias Lehner… Est-ce que ce nom vous dit quelque chose ?', ''),
(9841, 0, 'frFR', 'Vous allez bien ? Je viens vous ramener au fort du Givre, si vous pouvez marcher.', ''),
(9842, 0, 'frFR', 'Désolé de ne pas être arrivé plus tôt. Que s’est-il passé ?', ''),
(9843, 0, 'frFR', 'Je vais chercher de l’aide. Tenez bon.', ''),
(9848, 0, 'frFR', 'Pourriez-vous réparer mon matériel ?', ''),
(9852, 0, 'frFR', 'Gymer, où sont Algar, Navarius et Thrym ?', ''),
(9852, 1, 'frFR', 'Gymer, qu’y a-t-il à savoir ? Je n’ai jamais chevauché un géant.', ''),
(9852, 2, 'frFR', 'Gymer, je suis prêt. Allons-y !', ''),
(9853, 0, 'frFR', 'Comprenez-vous ce que je dis ? Nous devrions pouvoir communiquer maintenant.', ''),
(9853, 1, 'frFR', 'Je suis prêt, Brann. Assemblons la pierre-clé.', ''),
(9855, 0, 'frFR', 'J’ai encore quelques questions, Gymer.', ''),
(9856, 0, 'frFR', 'Montrez-moi vos marchandises.', ''),
(9857, 0, 'frFR', 'Je suis prêt - on va vous sortir d’ici.', ''),
(9859, 0, 'frFR', 'Je suis prêt - on va vous sortir d’ici.', ''),
(9860, 0, 'frFR', 'J’ai encore quelques questions, Gymer.', ''),
(9865, 0, 'frFR', 'Allons-y, sœurette.', ''),
(9866, 2, 'frFR', 'Faire de cette auberge votre foyer.', ''),
(9866, 3, 'frFR', 'Laissez-moi jeter un coup d’œil sur vos marchandises.', ''),
(9868, 0, 'frFR', 'Faire de cette auberge votre foyer.', ''),
(9868, 1, 'frFR', 'Laissez-moi jeter un coup d’œil sur vos marchandises.', ''),
(9869, 0, 'frFR', 'Je te défie en duel, vermine de la Croisade !', ''),
(9870, 0, 'frFR', 'J’ai entendu dire que les femmes vrykules ne savent pas du tout se battre. Si vous souhaitez me prouver le contraire, je vous invite à essayer.', ''),
(9871, 0, 'frFR', 'Je ne suis pas un ouvrier. Je suis ici pour vous libérer de votre servitude dans les mines.', ''),
(9873, 0, 'frFR', 'Entraînez-moi.', ''),
(9873, 1, 'frFR', 'Puis-je jeter un coup d’œil à vos recettes de gemmes anciennes ?', ''),
(9874, 0, 'frFR', 'Oubliez l’échauffement, ma sœur… ou est-ce que vous mesurer à quelqu’un de votre taille vous fait peur ?', ''),
(9875, 0, 'frFR', 'Désolé, Bricole, mais je ne peux pas me permettre de vous laisser me distraire pendant que je fais ce qu’il faut ici.', ''),
(9878, 0, 'frFR', 'J’ai une mauvaise nouvelle pour vous Onu’zun : je vais devoir mettre fin à vos rêves !', ''),
(9879, 0, 'frFR', 'Formez-moi', ''),
(9879, 1, 'frFR', 'Laissez-moi jeter un coup d’œil sur vos marchandises.', ''),
(9880, 0, 'frFR', 'J’ai trouvé cette étrange armure en plaques. Pouvez-vous m’en dire plus ?', ''),
(9891, 0, 'frFR', 'Le roi Foudrecœur m’envoie faire mes preuves comme le ferait un Givre-né. Je suis prêt pour mon épreuve, Fjorlin.', ''),
(9891, 1, 'frFR', 'Je suis prêt à rejoindre la bataille contre les wyrms. Avez-vous un aigle pour moi, Fjorlin ?', ''),
