(10912, 0, 'frFR', 'Comment puis-je apprendre à travailler la saronite primordiale ?', ''),
(10929, 0, 'frFR', 'J’ai une fusée qui porte votre nom, Chignard.', ''),
(10933, 0, 'frFR', 'Nous sommes prêts, Muradin.', ''),
