(10948, 0, 'frFR', 'Je voudrais une trousse de collectionneur de breloques ravissantes.', ''),
(10949, 0, 'frFR', 'Vos coups tordus ne m’intéressent pas, Brazie. Montrez-moi juste le « légal ».', ''),
