(12205, 0, 'frFR', 'Montez, ma belle.', ''),
(12210, 0, 'frFR', 'J’ai rencontré certains de ses hommes de main. Ils se sont montrés très hostiles.', ''),
(12211, 0, 'frFR', 'Oh oui, une sacrée opération c’est le moins qu’on puisse dire. Que pensez-vous de notre hôte ?', ''),
(12214, 0, 'frFR', 'Que savez-vous de notre généreux hôte, monsieur ?', ''),
(12215, 0, 'frFR', 'Hum, et qu’est-ce qui vous amène par ici ?', ''),
(12217, 0, 'frFR', 'En effet ! Et que pensez-vous du commandant, mon ami ?', ''),
(12218, 0, 'frFR', 'Toutes ces troupes, ces gardes… tout ça m’a l’air un petit peu excessif.', ''),
(12220, 0, 'frFR', 'Ahh, oui. Vous vous plaisez, ici ?', ''),
(12221, 0, 'frFR', 'Euh… Je ne sais pas vraiment. Il y a autre chose que vous pourriez me dire à son sujet ?', ''),
(12222, 0, 'frFR', 'Qu’est-ce que vous pensez de tous ces hommes armés ? Ça ne vous paraît pas un petit peu excessif ?', ''),
(12231, 0, 'frFR', 'Je suis prêt. Allons-y !', ''),
(12233, 0, 'frFR', 'Je suis intéressé par une formation de mage.', ''),
(12233, 1, 'frFR', 'Je voudrais oublier mes talents.', ''),
(12235, 0, 'frFR', 'Veuillez m’apprendre.', ''),
(12236, 0, 'frFR', 'Montrez-moi où je peux voler.', ''),
(12237, 0, 'frFR', 'Montrez-moi où je peux voler.', ''),
(12238, 0, 'frFR', 'Assez glandé ! Vous êtes en retard...', ''),
(12247, 0, 'frFR', 'Vous n’allez pas reculer, hein ?', ''),
(12253, 0, 'frFR', 'Vous pouvez disposer !', ''),
(12253, 1, 'frFR', '<Vous faites une série de gestes compliqués avec les mains.>', ''),
(12260, 0, 'frFR', 'De la glace, Bravorton. Je veux de la glace !', ''),
(12265, 0, 'frFR', 'Vous vous joignez à nous ?', ''),
(12266, 0, 'frFR', 'Mettez fin aux souffrances de cet Orc.', ''),
(12266, 1, 'frFR', 'Aider l''orc blessé à se relever.', ''),
(12268, 0, 'frFR', 'Je voudrais jeter un œil à vos marchandises, intendant.', ''),
(12271, 0, 'frFR', 'Dépêchez-vous, sortons d’ici !', ''),
(12272, 0, 'frFR', 'Attendez, je crois que je viens de recevoir quelque chose. C''est ça, sur ce bout de papier, là. Vous devez aller au sud-est jusqu''à la mine de Veine-Azur et vous présenter au capitaine Keyton. Le sud-est, c''est par là. *Vous indiquez le sud-est*', ''),
(12273, 0, 'frFR', 'Occupez-vous, allez faire une sieste par exemple. Je ne sais pas si j’ai du travail pour vous.', ''),
(12274, 0, 'frFR', 'D’accord, merci. Contentez-vous de vous diriger au sud-est. Plutôt sud qu’est. Probablement au large de la côte.', ''),
(12275, 0, 'frFR', 'Rien.', ''),
(12276, 0, 'frFR', 'Hum… On dirait qu’il y a des ennuis à Austrivage. Peut-être des insurgés worgens. Peut-être que vous pourriez aider ?', ''),
(12277, 0, 'frFR', 'C''EST TOUT, JOHNNY LA CLASSE, C''EST TOUT. C''EST À PRENDRE OÙ À LAISSER !', ''),
(12278, 0, 'frFR', 'Ben c''est tout.', ''),
(12279, 0, 'frFR', 'Euh, ben on a quelques problèmes aux champs Fangeux, au nord-est d’ici. Le gardien Eau-Plate aurait besoin d’aide.', ''),
(12280, 0, 'frFR', 'Vous pensez que vous pourriez réparer mon matos, Bavrian ?', ''),
(12284, 0, 'frFR', 'Qui aurait pu faire une chose pareille ?', ''),
(12285, 0, 'frFR', 'Vous allez mener l’enquête ?', ''),
(12286, 0, 'frFR', 'Bon, alors vous allez AU MOINS faire un papier dessus, hein ?', ''),
(12288, 0, 'frFR', 'Calmez-vous. Vous allez bien ?', ''),
(12289, 0, 'frFR', 'Vous avez vu ce qui est arrivé ?', ''),
(12290, 0, 'frFR', 'Peut-être que vous devriez aller vous allonger un peu.', ''),
(12292, 0, 'frFR', 'Je vais monter dedans et faire feu ! Il n’y a aucune raison que ça se passe mal !', ''),
(12296, 0, 'frFR', 'Deethuk, espèce de petit… Attendez un peu ! Qu’est-ce qui ne va pas avec cette machine à code ?', ''),
(12297, 0, 'frFR', 'Regardez ! Derrière vous ! Un miroir !', ''),
(12298, 0, 'frFR', 'Commandant, derrière vous ! Des parachutistes de Gnomeregan !', ''),
(12299, 0, 'frFR', 'Je suis prêt à avancer dans le canyon. La Brigade gob est prête ?', ''),
(12301, 0, 'frFR', 'Je suis prêt à affronter Torth !', ''),
(12314, 0, 'frFR', 'Vous ne voulez pas savoir ce qui lui est arrivé ?', ''),
(12315, 0, 'frFR', 'Tout ce qui compte, pour vous, ce sont les intérêts que vous avez dans l’opération ?', ''),
(12317, 0, 'frFR', 'Respirez un bon coup. Vous avez vu quelque chose ?', ''),
(12318, 0, 'frFR', 'Calmez-vous… Paniquer ne ferait qu''empirer la situation.', ''),
(12341, 0, 'frFR', 'Je cherche à progresser dans la voie du chasseur.', ''),
(12343, 0, 'frFR', 'Je suis prêt, Uchek !', ''),
(12344, 0, 'frFR', 'Je souhaiterais recevoir un entraînement de guerrier.', ''),
(12344, 1, 'frFR', 'Je voudrais oublier mes talents.', ''),
(12353, 0, 'frFR', 'Je viens mettre un terme à cette tuerie.', ''),
(12354, 0, 'frFR', 'D’accord, allons-y.', ''),
(12356, 0, 'frFR', 'Le roi Phaoris m’envoie m’enquérir de l’activité des gens de Neferset.', ''),
(12358, 0, 'frFR', 'Je peux peut-être vous aider. Est-ce que les gens de Neferset sont derrière tout ça ?', ''),
(12361, 0, 'frFR', 'Le roi souhaiterait être informé de toute activité récente du peuple de Neferset.', ''),
(12370, 1, 'frFR', 'Montre-moi où je peux aller.', ''),
(12371, 0, 'frFR', 'Examiner les peaux.', ''),
(12372, 0, 'frFR', 'Prendre une peau.', ''),
(12372, 1, 'frFR', 'Prendre deux peaux.', ''),
(12372, 2, 'frFR', 'Prendre trois peaux.', ''),
(12372, 3, 'frFR', 'Prendre quatre peaux.', ''),
