(12374, 2, 'frFR', 'Prendre trois bobines de fil.', ''),
(12374, 3, 'frFR', 'Prendre quatre bobines de fil.', ''),
(12376, 0, 'frFR', 'Je vous ai apporté des peaux, de la boue et du fil.', ''),
(12376, 2, 'frFR', 'Je vous ai apporté des peaux, de la boue et du fil.', ''),
(12381, 0, 'frFR', 'Je suis là pour vous aider à vous entraîner au combat, golem.', ''),
