(12385, 0, 'frFR', 'Récupérer le piston d''obsidienne', ''),
(12385, 1, 'frFR', 'Récupérer l''arbre à engrenages de thorium', ''),
(12397, 0, 'frFR', 'J’aimerais défier votre seigneur du magma en combat.', ''),
(12398, 0, 'frFR', 'On vous accuse d’être un démon déguisé, Navarax… si c’est votre vrai nom !', ''),
(12403, 0, 'frFR', 'Euuuhh, je suppose que je suis prêt…', ''),
(12408, 0, 'frFR', 'D’accord. Voyons de quoi vos lions sont capables.', ''),
(12409, 0, 'frFR', 'Je suis prêt à l’affronter !', ''),
(12410, 0, 'frFR', 'Entraînez-moi.', ''),
(12412, 0, 'frFR', 'Empruntez le portail pour rentrer à la halte de Cœur-Sauvage.', ''),
(12428, 0, 'frFR', 'Je dois voyager.', ''),
(12428, 1, 'frFR', 'J’ai un transport pour la clairière d’Arbrefer qui m’attend de la part de Fez Débreff.', ''),
(12428, 2, 'frFR', 'James Hallow m’a promis un transport vers la clairière de Griffebranche.', ''),
