(12439, 0, 'frFR', 'Je voudrais vous acheter quelque chose.', ''),
(12441, 0, 'frFR', 'Paré au départ, professeur Jones !', ''),
(12443, 0, 'frFR', 'Entraînez-moi.', ''),
(12443, 1, 'frFR', 'Laissez-moi jeter un coup d’œil sur vos marchandises.', ''),
