(12457, 2, 'frFR', '[Paillard] : Euh… « Oignon » !!!', ''),
(12458, 0, 'frFR', 'Je voudrais quitter cet endroit.', ''),
(12459, 0, 'frFR', 'Je dois escorter une livraison vers Havran’iliz.', ''),
(12460, 0, 'frFR', 'Montrez-moi où je peux voler.', ''),
(12462, 0, 'frFR', 'Montrez-moi où je peux voler.', ''),
(12464, 0, 'frFR', 'Allez ! On part pour le marais des Chagrins !', ''),
(12483, 0, 'frFR', 'Je ne suis pas une abomination, juste un Mort-vivant. Et je veux simplement vous parler.', ''),
(12484, 0, 'frFR', 'Lilian, vous réalisez que vous êtes vous-même une Morte-vivante ?', ''),
(12485, 0, 'frFR', 'Je ne suis pas venu pour me battre. On m’a seulement demandé de vous parler.', ''),
(12486, 0, 'frFR', 'Vous êtes libre de faire ce que vous voudrez.', ''),
(12487, 0, 'frFR', 'Vous ne vous souvenez pas ? Vous êtes mort.', ''),
(12488, 0, 'frFR', 'Calmez-vous, Valdred. Le fossoyeur Mordo vous en a probablement cousu de nouvelles.', '')
