(16331, 0, 'frFR', 'Je suis prêt, Khadgar. Utilisons l’anneau omnivoyant.', ''),
(16331, 1, 'frFR', 'Reparlons de la fois où nous avons utilisé l’anneau omnivoyant pour espionner Gul’dan et le Conseil des ombres.', ''),
(16331, 2, 'frFR', 'Reparlons de la fois où nous avons utilisé l’anneau omnivoyant pour espionner Gul’dan et le Conseil des ombres.', ''),
(16353, 0, 'frFR', 'Que pouvez-vous me dire sur cet endroit ?', ''),
(16357, 0, 'frFR', 'Je suis prêt à affronter Kaelynara.', ''),
(16367, 0, 'frFR', 'Je suis prêt à retourner à la mine Jorune.', ''),
(16370, 1, 'frFR', 'Parlez-moi de la bataille en haute mer (héroïque).', ''),
(16370, 2, 'frFR', 'Parlez-moi de la découverte du sombre cœur de la Pandarie (héroïque).', ''),
(16370, 3, 'frFR', 'Parlez-moi des secrets de Ragefeu (mode héroïque).', ''),
(16370, 4, 'frFR', 'Racontez-moi l’histoire du sang dans la neige (héroïque).', ''),
(16370, 5, 'frFR', 'Racontez-moi l’histoire d’une bière foudroyante (héroïque).', ''),
(16370, 6, 'frFR', 'Parlez-moi de la crypte des Rois oubliés (mode héroïque).', ''),
(16395, 0, 'frFR', 'Vous devez prendre une décision, Yrel. Vous battrez-vous pour la justice ? Ou laisserez-vous la peur régner sur vous ?', ''),
(16395, 5, 'frFR', 'Il faut bien commencer quelque part. Il n’y a pas si longtemps, je n’étais qu’un apprenti sur une île lointaine du nom de Shen Zin Su.', ''),
(16395, 8, 'frFR', 'Reprenez-vous, Yrel ! Vous valez mieux que cela !', ''),
(16396, 0, 'frFR', 'La force de la Lumière, ce sont ses champions. Ayez confiance en VOUS-MÊME.', ''),
(16396, 1, 'frFR', 'Il est vrai que « doutez de la Lumière », ça ne sonne pas aussi bien.', ''),
(16396, 2, 'frFR', 'Votre peuple a survécu à d’innombrables persécutions. Laisserez-vous ses espoirs s’éteindre ici, sans vous battre ?', ''),
(16416, 0, 'frFR', 'Je suis prêt pour la première épreuve de l’arène.', ''),
(16416, 1, 'frFR', 'Je suis prêt pour la deuxième épreuve de l’arène.', ''),
