(16416, 3, 'frFR', 'Je suis prêt pour la quatrième épreuve de l’arène.', ''),
(16416, 4, 'frFR', 'Je suis prêt pour la cinquième épreuve de l’arène.', ''),
(16423, 1, 'frFR', 'Thaelin, transformons ce bâtiment en corral.', 'La reconstruction du bâtiment nécessitera 10 000 pièces d''or.'),
(16431, 0, 'frFR', '<Toucher l’épée.>', ''),
(16438, 0, 'frFR', 'Vous avez l’air de vous y connaître en pêche. Vous croyez pouvoir nous aider ?\n\nNous avons établi un petit fief non loin d’ici, mais nous avons le plus grand mal à nourrir nos troupes. Si vous aviez des tuyaux à nous donner en ce qui concerne la pêche, ça nous aiderait vraiment.', ''),
(16448, 0, 'frFR', 'Qu’il en soit ainsi.', ''),
(16450, 0, 'frFR', 'Entrer dans l’Ordalie', ''),
(16454, 0, 'frFR', 'Je veux rester ici.', ''),
(16454, 1, 'frFR', 'Je voudrais vous acheter quelque chose.', ''),
(16461, 0, 'frFR', 'Contremaître, transformons ce bâtiment en cuirasserie.', 'Changer de bâtiment vous coûtera 5000 pièces d’or.\n\nVoulez-vous continuer ?'),
(16461, 1, 'frFR', 'Contremaître, transformons ce bâtiment en corral.', 'Changer de bâtiment vous coûtera 5000 pièces d’or.\n\nVoulez-vous continuer ?'),
(16462, 0, 'frFR', 'Permettez-moi de jeter un œil à vos biens.', ''),
(16464, 0, 'frFR', 'Laissez-moi jeter un coup d’œil sur vos marchandises.', ''),
(16467, 0, 'frFR', 'Que pouvez-vous me dire à propos de la Société de Conservation de Gentepression ?', ''),
