(16472, 2, 'frFR', 'Je voudrais regarder vos articles.', ''),
(16476, 0, 'frFR', 'Les ombres se rassemblent…', ''),
(16492, 0, 'frFR', 'Je suis avec vous, Gar’rok. Reposez avec honneur.', ''),
(16494, 0, 'frFR', 'Je voudrais connaître la vérité à propos de Dahaka. Que savez-vous sur sa mort ?', ''),
(16502, 0, 'frFR', 'Le fouiller à la recherche du martelet.', ''),
