(18936, 0, 'frFR', 'Écoutez attentivement, Cyana. Voici ce que j’ai appris grâce au Tome des secrets gangrenés.', ''),
(18937, 0, 'frFR', 'Êtes-vous prête à découvrir les secrets de la Légion, Kor’vas ?', ''),
(18939, 0, 'frFR', 'Battons-nous !', ''),
(18940, 0, 'frFR', 'Oui. J’accepte de devenir votre long-voyant !', ''),
(18943, 0, 'frFR', 'Envoyez-moi à la crique de l’Épave, s’il vous plaît.', ''),
(18943, 1, 'frFR', 'Montrez-moi où je peux voler.', ''),
(18944, 0, 'frFR', 'Oui !', ''),
(18958, 0, 'frFR', 'Il y a un autre moyen, Thaedris. Nous avons un refuge non loin d’ici. Thalyssra nous y attend.', ''),
(18959, 0, 'frFR', 'Entendu.', ''),
(18961, 0, 'frFR', 'Je souhaite jeter un coup d’œil à vos marchandises.', ''),
(18961, 1, 'frFR', 'Vous n’auriez pas un pied-de-biche en trop, par hasard ?', ''),
(18962, 0, 'frFR', 'Je souhaite jeter un coup d’œil à vos marchandises.', ''),
(18962, 1, 'frFR', 'Auriez-vous des présentoirs à armure dont vous n’avez pas besoin ?', ''),
(18962, 2, 'frFR', 'Voici votre robe. Puis-je avoir les présentoirs d''armure maintenant ?', ''),
(18963, 0, 'frFR', 'Je veux rester ici.', ''),
(18963, 1, 'frFR', 'Permettez-moi de jeter un œil à vos biens.', ''),
(18966, 0, 'frFR', 'Que comptez-vous faire, à présent ?', ''),
(18967, 0, 'frFR', 'Nous avons peut-être trouvé un moyen d’apaiser la faim le temps de trouver un remède. Laissez-nous vous aider.', ''),
(18971, 0, 'frFR', 'Je suis prêt.', ''),
(18973, 0, 'frFR', 'Essayer de réveiller le Vrykul.', ''),
(18977, 0, 'frFR', 'Je me demandais si vous pourriez vous séparer d''une de vos écailles ?', ''),
(18980, 0, 'frFR', 'Je me demandais si vous pourriez vous séparer d''une de vos écailles ?', ''),
(18983, 1, 'frFR', 'Celea m’envoie vous libérer. Tenez, mettez cette armure.', ''),
(18983, 2, 'frFR', 'Je suis prêt, Taldranis. Allons-y.', ''),
(18987, 0, 'frFR', 'Je ne suis pas un Naga, Stokalfr ! C’est Brandolf qui m’envoie !', ''),
(18992, 0, 'frFR', 'Chaparde des pièces dorées dans les tombes du cimetière voisin.', ''),
(18992, 1, 'frFR', 'Va chercher les machins brillants ! Creuse là où y a les morts.', ''),
(18993, 0, 'frFR', 'Autre chose ?', ''),
(18994, 0, 'frFR', 'Autre chose ?', ''),
(18995, 0, 'frFR', 'Tue le basilic le plus coriace qui hante ces cavernes et rapporte-moi sa dépouille !', ''),
(18995, 1, 'frFR', 'Tuer basilic ! Plus gros de la caverne ! Ensuite, rapporter son cadavre !', ''),
(18997, 0, 'frFR', 'Utilise une cire de premier choix pour fabriquer une bougie magique digne du roi des bougies.', ''),
(18997, 1, 'frFR', 'Fabrique une grosse bougie ! Plein de cire !', ''),
(19000, 0, 'frFR', 'Utilise ta pioche pour extraire les métaux précieux du plus gros filon de la caverne et rapporte-moi des échantillons.', ''),
(19000, 1, 'frFR', 'Creuse pierres et rapporte les plus belles ! Plus c’est belles, mieux c’est.', ''),
(19002, 0, 'frFR', 'Tu gardes une. Je prends le reste.', ''),
(19003, 0, 'frFR', 'Beau travail bien mort ! Belle récompense pour toi…', ''),
(19003, 1, 'frFR', '<Donner la botte à Tâte-Dent.>', ''),
(19004, 0, 'frFR', 'Moi avoir ce qu’il faut pour ça…', ''),
(19008, 0, 'frFR', '<Effectuer le rituel terrestre.>', ''),
(19012, 0, 'frFR', 'Alors, ce sera Kayn ou Altruis ?', ''),
(19015, 0, 'frFR', 'Mystique, merci pour votre sacrifice.', ''),
(19016, 0, 'frFR', 'Sevis, je dois vous sacrifier pour alimenter le portail.', ''),
(19016, 1, 'frFR', 'Vous devez me sacrifier pour alimenter le portail.', ''),
(19033, 0, 'frFR', 'On me dit que vous détenez certaines informations à propos d’une arme ancienne.', ''),
(19035, 0, 'frFR', 'Vous aviez un plan, tous les deux ?', ''),
(19038, 0, 'frFR', 'Apprenez-moi le travail du cuir.', ''),
(19041, 0, 'frFR', 'J’aimerais vous acheter quelque chose.', ''),
(19042, 0, 'frFR', '« Nous reboirons au puits. »', ''),
(19044, 0, 'frFR', 'J’aimerais consulter la liste des armes qui s’offrent à nous.', ''),
(19045, 0, 'frFR', 'Qu’à cela ne tienne, j’ai la solution.', ''),
(19046, 0, 'frFR', '<Montrer les runes à Apata et lui expliquer comment franchir la rivière.>', ''),
(19059, 0, 'frFR', 'Le pouvoir de la faux nous aiderait à vaincre la Légion, un objectif bien loin d’être maléfique, vous ne trouvez pas ?', ''),
(19059, 1, 'frFR', 'Je n’ai pas de temps à perdre en divagations ! La Légion ardente est une force plus maléfique encore !', ''),
(19059, 2, 'frFR', 'Si vous vous taisez, j''arracherai les réponses de votre âme ! <Attaque>', ''),
(19061, 0, 'frFR', 'Si nous restons inactifs, ce monde sera pris par Sargeras. Et alors il ne restera rien de votre Lumière du ciel ! Quel sera alors votre devoir ?', ''),
(19061, 1, 'frFR', 'Si nous restons inactifs, ce monde sera pris par Sargeras. Et alors il ne restera rien de votre Lumière du ciel ! Quel sera alors votre devoir ?', ''),
(19061, 2, 'frFR', 'Tant pis, j’arracherai de mes mains les réponses dont j’ai besoin ! <Attaquer>', ''),
(19062, 0, 'frFR', 'Détrompez-vous. J’étais là quand les démons ont attaqué le rivage Brisé et décimé nos rangs, combattants pieux et impies confondus. Si nous ne reprenons pas le dessus dès maintenant, nous sommes tous perdus.', ''),
(19062, 1, 'frFR', 'J''ai vu comment les corps de vos saints guerriers gisaient côte à côte à la tombe de Sargeras ! La Légion n''avait pas encore une telle armée, et cette fois votre seule Lumière céleste ne nous sauvera pas d''elle !', ''),
(19062, 2, 'frFR', 'Assez ! Répondez-moi ou mourez, prêtre ! <Attaque>', ''),
(19068, 0, 'frFR', 'Pourquoi n’apportez-vous pas cette lettre vous-même, seigneur Grisetête ?', ''),
(19069, 0, 'frFR', 'Que le brassage commence !', ''),
(19071, 0, 'frFR', 'Il paraît que tu connais une histoire à propos d’une paire de lames mystérieuses.', ''),
(19073, 0, 'frFR', 'Quitter les enclos Lugubres.', ''),
(19075, 0, 'frFR', 'Je vous apporte une lettre de votre père.', ''),
(19075, 1, 'frFR', 'Ça ne peut pas attendre. Il y a des démons dans nos rangs. Laissez-moi vous montrer.', ''),
(19076, 0, 'frFR', 'Allons-y, Tigre blanc.', ''),
(19078, 0, 'frFR', 'Je suis paré au combat !', ''),
(19081, 0, 'frFR', 'Parlons boutique.', ''),
(19081, 1, 'frFR', 'J’aimerais me présenter.', ''),
(19091, 0, 'frFR', 'Je veux me remémorer encore une fois les armes que nous devons trouver.', ''),
(19091, 2, 'frFR', 'Le roi Ymiron a combattu farouchement, mais il a été vaincu.', ''),
(19091, 3, 'frFR', 'Je suis prêt à commencer l’épreuve, Odyn.', ''),
(19092, 0, 'frFR', 'Je suis ici pour inspecter le joyau que Tiffany Kartier a taillé pour vous.', ''),
(19092, 1, 'frFR', 'Catriona, il paraît que quelqu’un vous cherche, en bas.', ''),
(19093, 0, 'frFR', 'Je suis ici pour inspecter les éclats de gemmes que Tiffany Kartier vous a donnés.', ''),
(19093, 1, 'frFR', 'Apprenez-moi l''ingénierie.', ''),
(19094, 0, 'frFR', 'Je suis ici pour inspecter les joyaux que Tiffany Kartier vous a donnés.', ''),
(19094, 1, 'frFR', 'J’aimerais vous acheter quelque chose.', ''),
(19100, 0, 'frFR', 'Rehgar et moi sommes prêts !', ''),
(19102, 0, 'frFR', 'J’aimerais mettre mon familier à l’écurie.', ''),
(19102, 1, 'frFR', 'Avez-vous réussi à mettre la main sur des raretés ?', ''),
(19102, 2, 'frFR', 'J’aimerais soigner et ressusciter mes mascottes de combat.', 'Je demande une participation aux frais de matériel.'),
(19103, 0, 'frFR', 'Je suis ici pour récupérer les joyaux que vous avez volés.', ''),
(19110, 0, 'frFR', 'Poursuivons les recherches sur mon arme prodigieuse.', ''),
(19115, 0, 'frFR', 'J’aimerais consulter la liste des armes qui s’offrent à nous.', ''),
(19115, 1, 'frFR', 'BM', ''),
(19115, 2, 'frFR', 'MM', ''),
(19116, 0, 'frFR', 'Emmenez-moi dans l’enceinte du fort Grommash.', ''),
(19118, 0, 'frFR', 'Que vous est-il arrivé ?', ''),
(19118, 1, 'frFR', 'Voici votre sac, Jabrouf.', ''),
(19122, 0, 'frFR', 'Très bien, Jabrouf. Je suis prêt à y aller.', ''),
(19123, 0, 'frFR', 'Je cherche un maître joaillier.', ''),
(19126, 0, 'frFR', 'Qu’est-il arrivé ensuite ?', ''),
(19128, 0, 'frFR', 'J’en ai aussi entendu parler.', ''),
(19130, 0, 'frFR', 'J’ai changé d’avis. Laissez-moi choisir une autre arme prodigieuse.', ''),
(19130, 1, 'frFR', 'J’aimerais me faire rembourser les traits de mon arme prodigieuse.', ''),
(19132, 0, 'frFR', 'J’ai pris ma décision. Sevis, sacrifiez-moi pour alimenter le portail.', ''),
(19132, 1, 'frFR', 'Un instant, Sevis. Laissez-moi réfléchir.', ''),
(19133, 0, 'frFR', 'J’en suis certain, Sevis. Je dois vous sacrifier pour alimenter le portail.', ''),
(19133, 1, 'frFR', 'Un instant, Sevis. Laissez-moi réfléchir.', ''),
