(19138, 2, 'frFR', 'Voici votre diamant !', ''),
(19140, 0, 'frFR', 'Payer les 175 pièces d’or.', 'Voulez-vous vraiment payer ?'),
(19140, 1, 'frFR', 'Je vais tâcher de vous rendre le service dont vous m’avez parlé.', ''),
