(19147, 0, 'frFR', '(Courtois) 250 pièces d’or, c’est beaucoup trop pour un seul diamant. Que diriez-vous de 25 ?', ''),
(19147, 1, 'frFR', '(Agressif) 250 pièces d’or pour un diamant ? C’est du vol ! Je vous en donne 10.', ''),
(19147, 2, 'frFR', 'Payer les 250 pièces d’or.', 'Voulez-vous vraiment payer ?'),
