(19174, 0, 'frFR', 'Ouvrir la caisse.', ''),
(19175, 0, 'frFR', 'Très bien, Jace. Je vais utiliser ma vision spectrale pour examiner cette grotte.', ''),
(19176, 0, 'frFR', 'Pour le sang et l’honneur, chef de guerre !', ''),
(19176, 1, 'frFR', 'Ça ne peut pas attendre. Il y a des démons dans nos rangs. Laissez-moi vous montrer.', ''),
(19198, 0, 'frFR', 'Nous sommes prêts à vous défier, Odyn !', 'Voulez-vous lancer le combat ?'),
(19199, 0, 'frFR', 'Tout est arrivé soudainement. Où sommes-nous ? Que se passe-t-il ?', ''),
(19199, 1, 'frFR', 'Le diacre de l’ombre ? Mais qui est donc ce nouveau chef ?', ''),
(19199, 2, 'frFR', 'Vous avez parlé de ce que $gil a fait:elle a fait; avec une sorte de lame magique. Pouvez-vous m''en dire plus ?', ''),
