(19215, 1, 'frFR', 'Je suis prêt.', ''),
(19215, 2, 'frFR', 'Je suis prêt.', ''),
(19217, 0, 'frFR', 'Thalyssra se trouve près de Meredil. Pouvez-vous nous y téléporter ?', ''),
