(19224, 0, 'frFR', 'Cap sur Azsuna !', ''),
(19225, 0, 'frFR', 'Tâchez de rester en vie, Fei Li. Je dois m’occuper des autres.', ''),
(19225, 1, 'frFR', 'Oubliez les risques et faites-vous plaisir, Fei Li ! Je me charge de votre protection.', ''),
(19226, 0, 'frFR', 'Ne mettez pas votre vie en jeu, Nurong. Restez sur la défensive.', ''),
(19226, 1, 'frFR', 'Infligez autant de dégâts que possible, Nurong, même si vous devez prendre des risques. Je vous protégerai !', ''),
