(19301, 3, 'frFR', '<Acquérir Maîtrise des lignes telluriques pour 60 doses de |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t mana ancestral.>', 'Dépenser 60 doses de |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t mana ancestral pour acquérir Maîtrise des lignes telluriques ?'),
