(19334, 3, 'frFR', 'Que faites-vous sur les îles Brisées, Brann ?', ''),
(19336, 0, 'frFR', 'Je vais m’occuper des autres, long-voyant.', ''),
(19337, 0, 'frFR', 'Découvrez les positions de la Légion ardente en Azeroth.', ''),
(19338, 3, 'frFR', 'Je veux aller aux salles des Valeureux (donjon).', ''),
(19338, 11, 'frFR', 'J’aimerais vous acheter quelque chose.', ''),
(19339, 0, 'frFR', 'Pouvez-vous m’accorder la faculté de marcher sur l’eau ?', ''),
(19340, 0, 'frFR', 'Voilà le reste des fragments d’os.', ''),
(19340, 1, 'frFR', 'Vous vivez ici, à Totem-du-Tonnerre, Lessah ?', '')
ON DUPLICATE KEY UPDATE `OptionText` = IF(IFNULL(`OptionText`, '') = '', VALUES(`OptionText`), `OptionText`), `BoxText` = IF(IFNULL(`BoxText`, '') = '', VALUES(`BoxText`), `BoxText`);
INSERT INTO `gossip_menu_option_locale` (`MenuID`, `OptionID`, `Locale`, `OptionText`, `BoxText`) VALUES
(19341, 0, 'frFR', 'Êtes-vous prêt pour votre leçon ?', ''),
(19342, 0, 'frFR', 'Cap sur Tornheim !', ''),
(19344, 0, 'frFR', 'Je voudrais apprendre la pêche.', ''),
(19344, 1, 'frFR', 'J’aimerais vous acheter quelque chose.', ''),
(19350, 0, 'frFR', 'Placez les trois pierres rituelles de Haut-Roc dans le cristal.', ''),
(19352, 0, 'frFR', 'Placez les trois Pierres rituelles de Haut-Roc dans le cristal.', 'Vous allez supprimer 3 |cFF00FF00|Hitem:130904:0:0:0:0:0:0:0:90:0|h[pierres rituelles de Haut-Roc]|h|r de votre inventaire. Continuer ?'),
(19354, 0, 'frFR', 'Placez les trois Pierres rituelles de Haut-Roc dans le cristal.', 'Vous allez supprimer 3 |cFF00FF00|Hitem:130904:0:0:0:0:0:0:0:90:0|h[pierres rituelles de Haut-Roc]|h|r de votre inventaire. Continuer ?'),
(19355, 0, 'frFR', 'Cap sur Tornheim !', ''),
(19357, 0, 'frFR', 'Avez-vous l’échantillon cauchemardesque ?', ''),
(19360, 0, 'frFR', 'Très bien.', ''),
(19363, 0, 'frFR', 'Je vais informer les autres gardiennes du triste sort de Cordana.', 'Voulez-vous vraiment quitter l’instance ?'),
(19364, 1, 'frFR', 'Que faites-vous sur les îles Brisées, haut-examinateur ?', ''),
(19365, 0, 'frFR', 'Quelles possibilités s’offrent à moi, déjà ?', ''),
(19368, 0, 'frFR', 'Malheureusement, oui.', ''),
(19393, 0, 'frFR', 'Je suis prêt.', ''),
(19397, 0, 'frFR', 'Avez-vous connaissance d’une arme susceptible de nous aider dans notre combat contre la Légion ?', ''),
(19399, 0, 'frFR', 'À l’en croire, vous détiendriez des informations sur une arme très ancienne.', ''),
(19400, 0, 'frFR', 'G’Hanir est tombé sous l’emprise du Cauchemar.', ''),
(19403, 0, 'frFR', 'Racontez-moi leur histoire.', ''),
(19405, 1, 'frFR', 'Sur mon honneur, il ne vous sera fait aucun mal, prêtresse.', ''),
(19406, 0, 'frFR', 'Que s’est-il passé ici ?', ''),
(19408, 0, 'frFR', 'Je suis fin prêt !', ''),
(19419, 1, 'frFR', 'Je suis prêt.', ''),
(19420, 0, 'frFR', 'Je suis prêt.', ''),
(19421, 0, 'frFR', 'Oui.', ''),
(19422, 5, 'frFR', 'Impliquer Tyrande.', ''),
(19423, 0, 'frFR', 'Conduisez-moi au temple des Cinq matins.', ''),
(19431, 0, 'frFR', 'C’est Thalyssra qui m’envoie.', ''),
(19432, 0, 'frFR', 'C’est vous, Silgryn ?', ''),
(19433, 0, 'frFR', 'Je suis prêt à partir.', ''),
(19434, 0, 'frFR', 'Je vois.', ''),
(19435, 0, 'frFR', 'Je vois.', ''),
(19436, 0, 'frFR', 'Qu’avez-vous trouvé jusqu’à présent ?', ''),
(19438, 0, 'frFR', '<Donner l’élixir de suspension à Shinfel.>', ''),
(19440, 0, 'frFR', 'Êtes-vous Ernie le Cinglé ?', ''),
(19442, 0, 'frFR', 'C’est Ritssyn qui m’envoie. Nous avons besoin d’aide pour conjurer une funeste malédiction.', ''),
(19458, 1, 'frFR', 'Téléportez-moi auprès d’Elerethe Ranfarouche.', ''),
(19458, 3, 'frFR', 'Téléportez-moi auprès des dragons du Cauchemar.', ''),
(19461, 3, 'frFR', 'Je veux me téléporter vers la lame-sort d''Aluriel.', ''),
(19463, 0, 'frFR', 'Qui est cette sorcière serpent ?', ''),
(19463, 1, 'frFR', 'Nous recherchons justement un bâton magique ! De quoi a-t-il l’air ?', ''),
(19463, 2, 'frFR', 'Nous cherchons une chamane. L’as-tu vue ?', ''),
(19463, 3, 'frFR', 'Joins-toi à nous ! Nous allons tuer la « sorcière serpent » et lui prendre son « bâton magique » !', ''),
(19467, 0, 'frFR', 'Allons-y !', ''),
(19468, 0, 'frFR', 'Allons-y.', ''),
(19469, 0, 'frFR', 'Je suis prêt.', 'Voulez-vous vraiment commencer le combat ?'),
(19470, 0, 'frFR', '<Fouiller le corps à la recherche d’indices.>', ''),
(19472, 0, 'frFR', 'Les ombres révèlent ce qu’elles dissimulaient.', ''),
(19472, 1, 'frFR', '<Remettre la rune des portails à Val’zuun>', ''),
(19472, 2, 'frFR', 'Qu’êtes-vous, au juste ?', ''),
(19473, 0, 'frFR', 'Revenons à l’affaire qui nous occupe.', ''),
(19474, 0, 'frFR', 'Je suis prêt.', ''),
(19475, 0, 'frFR', 'Lespin veut récupérer sa sculpture.', ''),
(19476, 0, 'frFR', 'Les ombres révèlent ce qu’elles dissimulaient.', ''),
(19476, 1, 'frFR', '<Poser votre insigne sur la table.>', ''),
(19476, 2, 'frFR', 'Montrez-moi votre dernier arrivage.', ''),
(19483, 0, 'frFR', 'Tout le monde est prêt, Grash. Défonce le mur de glace !', ''),
(19485, 0, 'frFR', 'Je suis prêt.', 'Voulez-vous vraiment commencer le combat ?'),
(19486, 0, 'frFR', 'Ouvrez le portail.', ''),
(19498, 0, 'frFR', '<Ricanement> Les démons, non, mais franchement… <Vous levez les yeux au ciel.>', ''),
(19499, 0, 'frFR', '<Ricanement> Les démons, non, mais franchement… <Vous levez les yeux au ciel.>', ''),
(19501, 0, 'frFR', 'Les démonistes ne sont certes pas réputés pour leur fiabilité. Et si Gul’dan nous trahissait ?', ''),
(19502, 0, 'frFR', 'Comment pourrions-nous être libres dans l’ombre de la Légion ?', ''),
(19503, 0, 'frFR', 'Comment allez-vous, compatriote sacrenuit ?', ''),
(19504, 0, 'frFR', '<Se contenter de lancer un clin d’œil de temps en temps.>', ''),
(19505, 0, 'frFR', 'N’y a-t-il donc personne pour s’opposer à Élisande ?', ''),
(19506, 0, 'frFR', 'Et si nous arrêtions de rester les bras croisés pendant que notre monde est réduit en cendres ? Juste une fois, pour voir.', ''),
(19507, 0, 'frFR', 'Comment pourrions-nous être libres dans l’ombre de la Légion ?', ''),
(19509, 0, 'frFR', 'Je vais te protéger, Grash. C’est promis. Ouvre-nous un passage en défonçant tout !', ''),
(19513, 0, 'frFR', 'Pas de cette manière…', ''),
(19515, 0, 'frFR', 'Envoyer un signal à Ly’leth Lunastre.', ''),
(19516, 0, 'frFR', 'Orik affirme que vous êtes capable de parler à ces esprits. Comment devons-nous nous y prendre ?', ''),
(19517, 0, 'frFR', 'D’accord.', ''),
(19519, 0, 'frFR', 'Je souhaiterais vous parler d’un certain dessin de gemme.', ''),
(19521, 0, 'frFR', 'Je voudrais me rendre à Dalaran.', ''),
(19522, 0, 'frFR', 'Qui a invoqué tous ces diablotins ?', ''),
(19522, 1, 'frFR', 'Avouez vos crimes !', ''),
(19524, 0, 'frFR', 'Lespin veut récupérer sa broche.', ''),
(19526, 0, 'frFR', 'Chef, pourriez-vous faire griller cette cuisse de faucon des plaines pour moi ?', ''),
(19526, 1, 'frFR', 'Je voudrais suivre la voie du grill.', ''),
(19540, 0, 'frFR', 'Le corbeau croasse.', ''),
(19540, 1, 'frFR', '<Poser votre insigne sur la table.>', ''),
(19540, 2, 'frFR', 'Montrez-moi ce que vous avez.', ''),
(19541, 0, 'frFR', 'Je vous ai dégagé un chemin. Vous pouvez vous échapper à condition de vous dépêcher !', ''),
(19542, 0, 'frFR', 'Hum… ?', ''),
(19545, 0, 'frFR', 'Je suis prêt à prendre une décision.', ''),
(19547, 0, 'frFR', 'Parlez-moi de votre plan.', ''),
(19550, 0, 'frFR', 'Parlez-moi de votre plan.', ''),
(19554, 0, 'frFR', '<Prendre un verre.>', ''),
(19555, 0, 'frFR', 'Je vous choisis comme sixième membre.', ''),
(19557, 1, 'frFR', 'Si un voleur y touchait, nul doute que quelqu’un s’en apercevrait.', ''),
(19558, 1, 'frFR', 'Cet assemblage elfique défectueux vous est familier et peut être modifié pour fournir un renforcement magique.', ''),
(19560, 0, 'frFR', 'Le temps presse. Fuyez !', ''),
(19561, 0, 'frFR', 'Le temps presse. Fuyez !', ''),
(19563, 0, 'frFR', 'J’accepte votre épreuve, Yrgrim.', ''),
(19565, 0, 'frFR', 'Le temps presse. Fuyez !', ''),
(19566, 0, 'frFR', 'Enchanté, dame Ly’leth.', ''),
(19567, 0, 'frFR', 'Enchanté de vous rencontrer, dame Lee.', ''),
(19568, 0, 'frFR', 'Suivez-moi. Ly’leth veut vous parler.', ''),
(19569, 0, 'frFR', 'Nous avons besoin de votre aide pour négocier avec le roi d’en bas.', ''),
(19570, 0, 'frFR', 'Nous avons besoin de votre aide pour négocier avec le roi d’en bas.', ''),
(19571, 0, 'frFR', 'Lespin veut récupérer sa broche.', ''),
(19572, 0, 'frFR', 'Je suis prêt.', ''),
(19573, 0, 'frFR', 'Il insiste pour que vous la lui rendiez, de gré ou de force.', ''),
(19575, 0, 'frFR', 'Je suis prêt.', ''),
(19576, 0, 'frFR', 'Je vous apporte une perle de sagesse arcanique. Qu’est-ce que vous faites ici, au juste ?', ''),
(19580, 0, 'frFR', 'Je suis prêt.', ''),
(19584, 0, 'frFR', 'Battons-nous !', ''),
(19585, 0, 'frFR', 'Ly’leth vous demande. C’est à propos d’une cargaison de bulbes de lys crépusculaire.', ''),
(19586, 0, 'frFR', '<Prélever un petit échantillon de sang.>', ''),
(19586, 1, 'frFR', '<Obtenir le sang à l’aide de votre magie noire.>', ''),
(19589, 0, 'frFR', 'Nous pouvons commencer.', ''),
(19599, 0, 'frFR', 'Je suis prêt.', ''),
(19600, 0, 'frFR', 'Racontez-moi leur histoire.', ''),
(19601, 0, 'frFR', 'Entraînez-moi.', ''),
(19601, 1, 'frFR', 'Permettez-moi de jeter un œil à vos biens.', ''),
(19604, 0, 'frFR', 'Pourquoi voulez-vous rejoindre la Société empyréenne ?', ''),
(19606, 0, 'frFR', 'Grek, voudrais-tu essayer cette nouvelle huile pour arme que Rakoria a faite ?', ''),
(19610, 0, 'frFR', 'J’ai besoin de vos pouvoirs.', ''),
(19611, 0, 'frFR', 'Alors, comme ça, l’auguste Thal’kiel a fini par se soumettre aux démons.', ''),
(19612, 0, 'frFR', 'Dans ce cas, laissez-moi vous délivrer. Ensemble, nous mettrons la Légion ardente à notre merci ! Nous régnerons en maîtres incontestés !', ''),
(19624, 0, 'frFR', 'Oui, inscrivez-moi pour la baston !', ''),
(19626, 0, 'frFR', '« Au corps à corps ? J’ai peur que tous mes champions soient bel et bien armés. »', ''),
(19626, 1, 'frFR', '« Mais pourquoi oser une telle stupidité ? »', ''),
(19626, 2, 'frFR', '« Espèce de bouffon insolent ! Je devrais vous faire décapiter pour cet outrage ! »', ''),
(19627, 0, 'frFR', '« Pourquoi ai-je le sentiment que "cachot" est le nom de la chambre à coucher de Votre Majesté ? »"', ''),
(19627, 1, 'frFR', '« Eh bien, adieu alors. »', ''),
(19629, 0, 'frFR', '« Hélas, Votre Altesse, ce Gnome est bien seul. Mais il maîtrise toutefois certains sortilèges… »', ''),
(19629, 1, 'frFR', '« Ah, vous m’avez percé à jour. Très bien, permettez-moi de leur rendre leur liberté sur-le-champ. »', ''),
(19630, 0, 'frFR', '« Bien entendu. Presque toutes les femmes que je croise y ont droit. Après tout, mon amour-propre ne se mesure-t-il pas à l’aune du nombre de mes aventures amoureuses ? »', ''),
(19630, 1, 'frFR', '« Non, Votre Majesté. Seules en sont dignes les princesses aux yeux de saphir battu par les tempêtes. »', ''),
(19631, 0, 'frFR', '« Vous êtes aussi belle que les deux lunes d’Azeroth réunies… »', ''),
(19631, 1, 'frFR', '« Ce que je voulais dire, c’est… VRAIMENT mignonne. »', ''),
(19632, 0, 'frFR', '« Et heu… vous venez souvent ici ? Ah, et que pensez-vous du temps qu’il fait ? »', ''),
(19632, 1, 'frFR', '« Ha, regardez-moi ça, si c’est minable ! » <Gonfle ses biceps.>', ''),
(19633, 0, 'frFR', '« Alors, à l’évidence, Votre Majesté, vous seule pouvez relever mon… gant. »', ''),
(19633, 1, 'frFR', '« Dommage ! Je n’ai plus qu’à rengainer mon épée. »', ''),
(19634, 0, 'frFR', '« Hum… Gaaa… Sire Morfléau ? »', ''),
(19634, 1, 'frFR', '« Vous êtes vraiment mignonne. »', ''),
(19635, 0, 'frFR', '« Mais Votre Majesté… pourquoi prendre ma tête, alors que vous vous êtes déjà emparée de mon cœur ? »', ''),
(19635, 1, 'frFR', '« Houla ! Pitié, Votre Majesté ! »', ''),
(19637, 0, 'frFR', 'Tout effacer et recommencer.', ''),
(19645, 0, 'frFR', 'Laissez-moi jeter un coup d’œil sur vos marchandises.', ''),
(19646, 0, 'frFR', 'Qui veut du boulot ?', ''),
(19665, 0, 'frFR', '<Montrer discrètement votre insigne.>', ''),
(19665, 1, 'frFR', 'Montrez-moi votre dernier arrivage.', ''),
(19667, 0, 'frFR', 'Traiter la fièvre du patient.', ''),
(19681, 0, 'frFR', 'J’aimerais voir les enchantements que vous proposez.', ''),
(19682, 0, 'frFR', 'J’aimerais vous acheter quelque chose.', ''),
(19684, 0, 'frFR', 'Une mission ?', ''),
(19684, 1, 'frFR', 'L’évêque Farthing est parti, lui aussi ?', ''),
(19687, 0, 'frFR', 'Donner : 300 doses de |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t|Hcurrency:1155|h|cFFFFFFFF mana ancestral|h|r', ''),
(19689, 0, 'frFR', 'C’est vous que je choisis pour combattre à mes côtés.', ''),
(19692, 0, 'frFR', 'J’ai trouvé un fût de vin !', ''),
(19692, 1, 'frFR', '<Montrer votre cachet.>', ''),
(19693, 0, 'frFR', 'Êtes-vous en mesure de m’aider ?', ''),
(19696, 0, 'frFR', '<Montrer votre cachet à Arluin.>', ''),
(19696, 1, 'frFR', 'Vanthir et moi avons besoin de votre aide pour venger…', ''),
(19696, 2, 'frFR', 'Donner : 800 doses de |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t|Hcurrency:1155|h|cFFFFFFFF mana ancestral|h|r.', 'Vous êtes sur le point de dépenser 800 doses de mana ancestral. Voulez-vous continuer ?'),
(19696, 3, 'frFR', 'Nous avons besoin de votre aide pour « convaincre » certaines nobles maisons de soutenir la candidature de Ly’leth au poste de conseillère. C’est d’accord ?', ''),
(19696, 4, 'frFR', 'Donner : 1200 doses de |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t|Hcurrency:1155|h|cFFFFFFFF mana ancestral|h|r.', 'Vous êtes sur le point de dépenser 1200 doses de mana ancestral. Voulez-vous continuer ?'),
(19697, 0, 'frFR', 'Je suis prêt à communier avec les seigneurs élémentaires.', ''),
(19697, 1, 'frFR', 'Envoyez-moi au rivage Brisé !', ''),
(19699, 0, 'frFR', 'En effet. Je cherche un paladin, un certain Galford.', ''),
(19700, 0, 'frFR', 'À vrai dire, je l’ignore. Je vais partir à sa recherche.', ''),
(19704, 0, 'frFR', 'Le cruel tonnelier a rendu son dernier souffle.', ''),
(19705, 0, 'frFR', 'Le sabre rôde sur la place.', ''),
(19706, 0, 'frFR', 'Le hibou hulule à la nuit tombée.', ''),
(19708, 0, 'frFR', 'Galford portait une étincelle de l’essence de Tyr, mais Jotun l’a tué pour s’en emparer. J’en ai besoin pour récupérer le marteau de guerre.', ''),
(19710, 0, 'frFR', 'J’aimerais m’en remettre à la sagesse du conseil.', ''),
(19712, 0, 'frFR', 'Un ordre secret ?', ''),
(19717, 0, 'frFR', 'Je dois voyager.', ''),
(19717, 1, 'frFR', 'Il faut que je me rende à la Chute d’Ashamane.', ''),
(19718, 0, 'frFR', 'Je suis prêt. Allons-y !', ''),
(19719, 0, 'frFR', 'Voici la tête de la créature qui a tué votre mage.', ''),
(19722, 0, 'frFR', 'C’est bon pour mon déguisement. Allez-y.', ''),
(19726, 0, 'frFR', 'Battons-nous !', ''),
(19727, 0, 'frFR', 'Allons-y.', ''),
(19731, 0, 'frFR', 'Continuez…', ''),
(19733, 0, 'frFR', 'Continuez…', ''),
(19735, 0, 'frFR', 'Continuez…', ''),
(19739, 0, 'frFR', 'Continuez…', ''),
(19749, 0, 'frFR', 'Continuez…', ''),
(19751, 0, 'frFR', 'Continuez…', ''),
(19753, 0, 'frFR', 'Continuez…', ''),
(19757, 0, 'frFR', 'Continuez…', ''),
(19759, 0, 'frFR', 'Continuez…', ''),
(19761, 0, 'frFR', 'Continuez…', ''),
(19764, 0, 'frFR', 'Ne jouez pas les timides. Je sais bien que vous espionnez pour le compte de la grande magistrice.', ''),
(19765, 0, 'frFR', 'Ne jouez pas les timides. Je sais bien que vous espionnez pour le compte de la grande magistrice.', ''),
(19768, 0, 'frFR', 'Je suis prêt à commencer.', ''),
(19769, 0, 'frFR', 'Je suis prêt.', ''),
(19770, 0, 'frFR', 'Oui.', ''),
(19773, 0, 'frFR', 'J’aimerais vous acheter quelque chose.', ''),
(19774, 0, 'frFR', 'Hum… crôa ?', ''),
(19775, 0, 'frFR', 'Je veux faire un choix !', ''),
(19778, 0, 'frFR', 'J’aimerais pouvoir accéder au coffre personnel d’Alodi, archimage de Dalaran.', ''),
(19778, 1, 'frFR', 'Entendu, Gloutonia. Que cherche la Légion, à votre avis ?', 'Vous n’allez pas changer d’avis ?'),
(19779, 1, 'frFR', 'D’accord, mais elle s’appelle reviens.', ''),
(19781, 0, 'frFR', 'Montrez-moi vos marchandises.', ''),
(19783, 0, 'frFR', 'Vous souhaitiez me parler ?', ''),
(19783, 1, 'frFR', 'Commençons .', ''),
(19783, 2, 'frFR', 'Je suis prêt à combattre Korin !', ''),
(19792, 0, 'frFR', 'Je viens vous voir à propos d’Arrexis et de son rituel. Je dois affronter Balaadar et il me faut pour cela attirer son attention.', ''),
(19794, 0, 'frFR', 'J’aimerais vous acheter quelque chose.', ''),
(19796, 0, 'frFR', 'Je bénéficie de l’aide de Meryl Gangrorage et de l’esprit d’Alodi, et nous savons à quoi nous allons devoir faire face, cette fois.', ''),
(19797, 0, 'frFR', 'Je veux affronter vos démons, démoniste.', ''),
(19806, 0, 'frFR', 'Votre famille se trouve au Berceau du Marteau.', ''),
(19808, 0, 'frFR', 'Pourquoi chargez-vous les marchandises taurènes à bord de votre zeppelin ?', ''),
(19808, 1, 'frFR', 'Qu’avez-vous à vendre ?', ''),
(19812, 0, 'frFR', 'Qui veut du boulot ?', ''),
(19815, 0, 'frFR', 'Voilà toutes les furies que j’ai prises.', ''),
(19816, 0, 'frFR', 'Commençons les incantations.', ''),
(19819, 1, 'frFR', 'Ouvrez le portail.', ''),
(19822, 0, 'frFR', 'Allons-y, Kayn. Il es temps de convaincre Akama de rejoindre notre camp.', ''),
(19822, 1, 'frFR', 'Je vous suis totalement, Kayn. Espérons qu’il entende la voix de la raison. Dans le cas contraire…', ''),
(19823, 1, 'frFR', 'Vous ne me laissez guère le choix, Akama. D’une manière ou d’une autre, vous nous aiderez à vaincre la Légion.', ''),
(19828, 0, 'frFR', '<Montrer la carapace de crabe à Phin.>', ''),
(19828, 1, 'frFR', '<Montrer la pince de crabe à Phin.>', ''),
(19828, 2, 'frFR', '<Montrer l’huile de crabe à Phin.>', ''),
(19828, 3, 'frFR', '<Montrer le sable fin à Phin.>', ''),
(19829, 0, 'frFR', '<Donner du vin de mana.>', ''),
(19830, 0, 'frFR', '<Donner du vin de mana.>', ''),
(19831, 0, 'frFR', '<Donner du vin de mana.>', ''),
(19832, 0, 'frFR', '<Donner du vin de mana.>', ''),
(19836, 0, 'frFR', 'Je veux rester ici.', ''),
(19836, 1, 'frFR', 'Permettez-moi de jeter un œil à vos biens.', ''),
(19843, 0, 'frFR', 'J’aimerais étudier les informations dont nous disposons sur l’arme prodigieuse restante.', ''),
(19844, 8, 'frFR', 'Entrer dans l’Ordalie', ''),
(19852, 0, 'frFR', 'Je n’attends plus que vous. Allez-y, provoquez qui vous voulez !', ''),
(19854, 0, 'frFR', 'Parlez-moi de votre plan.', ''),
(19855, 3, 'frFR', 'Emmenez-moi au sentier Brise-Vent.', ''),
(19855, 4, 'frFR', 'Emmenez-moi au pic de Thorim, devant le refuge des Thorignirs.', ''),
(19855, 5, 'frFR', 'Emmenez-moi au sommet du pic de Thorim.', ''),
(19856, 0, 'frFR', 'Venez à l’aire de Krasus, nous devrions être en mesure d’aider votre ordre.', ''),
(19858, 0, 'frFR', 'Il faut d’abord que vous vous rendiez à l’aire de Krasus de toute urgence. C’est Tyrosus qui m’envoie.', ''),
(19859, 0, 'frFR', 'Vous allez devoir vous expliquer. Pourquoi nous avoir trahis ?', ''),
