(21272, 0, 'frFR', 'Il est bon de voir que la Lame-Ardente est en train de réussir là où le Conseil des ombres a échoué.', ''),
(21273, 0, 'frFR', 'Alors comme ça, la Lame brûlante est sacrifiable ?', ''),
(21274, 0, 'frFR', 'Si je peux faire quelque chose pour vous...', ''),
(21276, 0, 'frFR', 'Comment le savez-vous ? Je veux dire, oui... Je cherche le fragment. Est-ce que vous l’avez ?', ''),
(21277, 0, 'frFR', 'Très bien. Où ?', ''),
(21278, 0, 'frFR', '<Accepter le cristal.>', ''),
(21279, 0, 'frFR', 'Un poisson ? Vous avez donné un morceau de ce qui pourrait être la clé pour sauver toute vie sur Kalimdor à un poisson ?', ''),
(21280, 0, 'frFR', 'Un vairon ? Les océans sont remplis de vairons ! Il pourrait y en avoir cent millions de millions !', ''),
(21281, 0, 'frFR', '…', ''),
(21282, 0, 'frFR', 'Vous avez donné ce fragment à un vairon et lâché ce vairon quelque part dans la mer entre les royaumes de l’Est et ici ? Et ce vairon a des pouvoirs spéciaux ?', ''),
(21282, 1, 'frFR', 'Je suis prêt.', ''),
(21282, 2, 'frFR', 'Envoyez-moi à l''Exodar.', ''),
(21283, 0, 'frFR', 'Tu es fou à lier.', ''),
(21284, 0, 'frFR', 'Je suis tout ouïe.', ''),
(21285, 0, 'frFR', 'Je vous demande pardon ?', ''),
(21286, 0, 'frFR', 'D''accord, voyons si j''ai bien compris. Vous avez placé le sceptre confié à votre vol par Anachronos sur un vairon de votre fabrication et maintenant vous attendez de moi que je construise... une bouée d''arcanite ou je ne sais quoi... pour forcer votre vairon à sortir de sa cachette ? ET que j''encoure potentiellement la colère d''un seigneur élémentaire ? Ai-je oublié quelque chose ? Peut-être dois-je faire cela sans aucun vêtement, pendant une éclipse solaire, une année bissextile ?', ''),
(21287, 0, 'frFR', 'TRÈS BIEN ! Et comment, si je puis vous le demander, suis-je censé me procurer une bouée en arcanite ?', ''),
(21288, 0, 'frFR', 'Mais…', ''),
(21289, 0, 'frFR', 'Je crois en vous.', ''),
(21290, 0, 'frFR', 'J’ai besoin de réponses, l’ogre !', ''),
(21291, 1, 'frFR', 'Pourquoi les Boulderfist sont-ils si loin ? Vous savez que c''est le territoire des Kurenaï.', ''),
(21292, 2, 'frFR', 'Et tu penses que tu peux manger tout ce que tu veux ? Apparemment, tu essayes de manger les Roués de Telaar.', ''),
(21293, 3, 'frFR', 'Cela veut dire que c''est la guerre, Gros-tas ! La guerre !', ''),
(21295, 0, 'frFR', 'J''ai tué beaucoup de vos ogres, Lantresor. Je n''ai pas peur.', ''),
(21310, 0, 'frFR', 'Pourriez-vous me consacrer un moment, monsieur ?', ''),
(21311, 0, 'frFR', 'Hum… oui, bien sûr. Mais il y a quelque chose que vous devriez voir dans ce bâtiment, M. Garde-enclume.', ''),
(21312, 0, 'frFR', '<Transmettre les ordres de Fareeya.>', ''),
(21313, 0, 'frFR', 'Il n’y a qu’un chef de guerre, Eitrigg !', ''),
(21314, 0, 'frFR', 'Donnez-m’en la preuve.', ''),
(21315, 0, 'frFR', '<Transmettre les ordres de Fareeya.>', ''),
(21316, 0, 'frFR', 'Je vous rappellerai cette offre, Eitrigg.', ''),
(21317, 0, 'frFR', 'Ah, c''est donc ainsi qu''ils ont chassé les Sombrefer vers les zones inférieures du pic.', ''),
(21318, 0, 'frFR', 'Il existe peut-être un moyen ?', ''),
(21319, 0, 'frFR', 'Comme vous voulez, Eitrigg.', ''),
(21322, 0, 'frFR', 'Toutes mes excuses, je ne savais pas que vous compreniez ce que je dis. Que faites-vous ici ?', ''),
(21323, 0, 'frFR', '<Transmettre les ordres de Fareeya.>', ''),
(21324, 0, 'frFR', 'Quel marché ?', ''),
(21325, 0, 'frFR', 'Comment a-t-il rompu le marché ?', ''),
(21326, 1, 'frFR', 'Allons-y !', ''),
(21330, 0, 'frFR', 'Je n’ai commis aucune faute.', ''),
(21331, 0, 'frFR', 'Vous avez perdu la tête, Nefarius. Vous parlez en énigmes.', ''),
(21332, 0, 'frFR', 'Faites.', ''),
(21333, 0, 'frFR', 'Je ne peux pas, Vaelastraz ! Il doit bien y avoir un moyen de vous soigner !', ''),
(21334, 0, 'frFR', 'Vaelastraz, non !!', ''),
(21335, 0, 'frFR', 'Je suis prêt, Akama.', ''),
