(21423, 0, 'frFR', 'J’ai besoin de faire des réparations, Duraël.', ''),
(21451, 0, 'frFR', 'Qu’est-ce que c’est que ça, là, derrière vous ?', ''),
(21454, 0, 'frFR', 'Pourquoi y a-t-il un portail ici ?', ''),
(21456, 0, 'frFR', 'Intéressant… Et pourquoi ne portez-vous pas de chaussures ?', ''),
(21457, 0, 'frFR', 'Mais vous êtes assis.', ''),
