(22093, 0, 'frFR', 'Pourriez-vous m’invoquer de la nourriture ?', ''),
(22095, 0, 'frFR', 'Je veux trier le courrier !', ''),
(22095, 1, 'frFR', 'Je suis partant pour le défi ! Je veux trier les lettres avec une adresse incomplète.', ''),
(22129, 0, 'frFR', 'Je dois m’entretenir avec Magni Barbe-de-Bronze au plus vite.', ''),
(22143, 0, 'frFR', 'Je dois m’entretenir avec Magni Barbe-de-Bronze au plus vite.', ''),
(22145, 0, 'frFR', 'Il faut que je me rende au village de Sudevent.', ''),
(22209, 0, 'frFR', 'Khadgar m’a demandé de remettre cette lettre.', ''),
(23602, 0, 'frFR', 'Déserteur !', ''),
(25809, 0, 'frFR', 'L’attaque des sabrons a été repoussée. Vous pouvez partir, maintenant, et reposer en paix.', ''),
(26179, 0, 'frFR', 'Nous sommes prêts à vous emmener auprès de la Horde.', ''),
(26810, 0, 'frFR', 'Grand seigneur, êtes-vous prêt à rejoindre la Horde ?', ''),
(27245, 0, 'frFR', 'Votre éminence, puis-je m''entretenir avec vous en privé ?', ''),
(27378, 0, 'frFR', 'Votre heure est venue.', ''),
(28512, 0, 'frFR', 'Fournitures d’artisanat', ''),
(30190, 0, 'frFR', 'Parlez-moi de cette plaque.', ''),
(33001, 0, 'frFR', 'Attirer l''esprit de Thundris Tissevent.', ''),
(33033, 0, 'frFR', 'Attirer l''esprit hors du cadavre de la sentinelle Elissa Brise-étoile.', ''),
(33035, 0, 'frFR', 'Pousser le corps de Taldan à relâcher son esprit.', ''),
(33037, 0, 'frFR', 'Attirer l''esprit hors du cadavre immobile de Caylais Plumelune.', ''),
(33072, 0, 'frFR', 'Vénérable Onu, où puis-je trouver une Graine de la terre ?', ''),
(33178, 0, 'frFR', 'Je suis prêt. Commencez l’attaque.', ''),
(33440, 0, 'frFR', 'Allons, mon ami. Vous coupez et je vous protège des elfes, d''accord ?', ''),
(33837, 0, 'frFR', 'Donnez-moi une nouvelle poudre de signal secrète.', ''),
(34258, 0, 'frFR', 'Oui, je suis prêt. Allons-y ! ', ''),
(34578, 0, 'frFR', 'Montre-moi ce que tu vaux, Rocco. ', ''),
(35567, 0, 'frFR', '<Fusionner avec l''esprit.>', ''),
(35595, 0, 'frFR', 'Oui, archimage, je me cacherai dans la pierre.', ''),
(36296, 0, 'frFR', 'Lancez le combat.', ''),
(36436, 0, 'frFR', 'C''est Kalec qui m''envoie...', ''),
(36472, 0, 'frFR', '<Utiliser la sonnette>', ''),
(36561, 0, 'frFR', 'Taisez-vous, vomi de poils ! Bientôt vous apprendrez à vous soumettre à vos maîtres gnomes !!', ''),
(36561, 1, 'frFR', 'Vous feriez mieux de vous y habituer, viande séchée. L''Alliance vous considère surtout comme des animaux de compagnie. Savez-vous faire des tours ?', ''),
(36571, 0, 'frFR', 'Vous n''aurez pas le choix une fois votre peuple asservi par les escadrons de la mort de l''Alliance en bottes cloutées !', ''),
(36571, 1, 'frFR', 'Vous n''arrêtez pas de parler, mais je n''entends que « Bla bla bla, mon peuple se baigne dans sa propre crasse. »', ''),
(36571, 2, 'frFR', ' <Arracher son piercing au nombril.>', ''),
(36596, 0, 'frFR', 'Je suis prêt. Téléportez-moi au repaire des Noiregueules.', ''),
(36599, 0, 'frFR', '"Euh... Al''teth... la c''tolgar ? Ou quelque chose comme ça."', ''),
(36613, 0, 'frFR', 'Je veux utiliser ma banque, Gobber.', ''),
(36618, 0, 'frFR', 'Pas si vite, face d''ours. Il me faut d''abord un massage des pieds.', ''),
(36618, 1, 'frFR', 'C''est quoi cette odeur ? C''est vous ? Sérieusement.', ''),
(36618, 2, 'frFR', 'L''Alliance exige la livraison d''un bébé frais à chaque nouvelle lune pour nos camps de travail infantile.', ''),
(36799, 0, 'frFR', 'Aller à Vashj''ir', 'Voulez-vous vraiment vous rendre à Vashj''ir ?'),
(36859, 0, 'frFR', 'Non, non, non, vous ne comprenez pas. Je suis ici pour aider.', ''),
(36861, 0, 'frFR', 'Rencontré quelqu''un ? Je ne savais pas qu''il y avait d''autres dragons par ici.', ''),
(36863, 0, 'frFR', '...le guérisseur des esprits ?', ''),
(36865, 0, 'frFR', 'Je suis désolé, je ne voulais pas être impoli, je...', ''),
(36867, 0, 'frFR', 'Ce n''est pas du tout ce que je disais.', ''),
(36869, 0, 'frFR', 'Je suis le... laissez tomber. Je suis venu vous prévenir que le vol draconique noir est ici et vous traque.', ''),
(36871, 0, 'frFR', 'Vous le savez déjà ? Pourquoi n''allez-vous pas les arrêter, alors ?', ''),
(36873, 0, 'frFR', 'Mais Kalecgos est déjà là-bas pour essayer de les arrêter. Il a besoin de votre aide.', ''),
(36875, 0, 'frFR', 'Vous viendrez donc ?', ''),
(36877, 0, 'frFR', 'Je vais le prévenir tout de suite. Retrouvez-nous à Sable Ridge.', ''),
(37167, 0, 'frFR', 'J’ai retrouvé votre armure et vos armes. La victoire ou la mort !', ''),
