(45150, 0, 'frFR', 'Bonjour, madame. Avez-vous entendu des rumeurs intéressantes dernièrement ?', ''),
(45151, 0, 'frFR', 'Je cherche quelqu''un qui aurait volé des provisions à Hearthglen. Avez-vous une piste ?', ''),
