(46425, 0, 'frFR', 'Je cherche Tahet. Laissez-moi vous libérer de ces chaînes.', ''),
(46603, 0, 'frFR', 'Le roi Phaoris m’envoie m’enquérir de l’activité des gens de Neferset.', ''),
(46813, 0, 'frFR', 'Vous n’allez pas reculer, hein ?', ''),
(47176, 0, 'frFR', 'Oh oui, une sacrée opération c’est le moins qu’on puisse dire. Que pensez-vous de notre hôte ?', ''),
(47185, 0, 'frFR', 'Que savez-vous de notre généreux hôte, monsieur ?', ''),
(47187, 0, 'frFR', 'En effet ! Et que pensez-vous du commandant, mon ami ?', ''),
(47189, 0, 'frFR', 'Ahh, oui. Vous vous plaisez, ici ?', ''),
(47195, 0, 'frFR', 'Archigéomancien, je suis prêt pour le rituel.', ''),
(47434, 0, 'frFR', 'Vous vous joignez à nous ?', ''),
(47434, 1, 'frFR', 'Vous vous joignez à nous ?', ''),
(47434, 2, 'frFR', 'Vous vous joignez à nous ?', ''),
(47440, 0, 'frFR', 'C''EST TOUT, JOHNNY LA CLASSE, C''EST TOUT. C''EST À PRENDRE OÙ À LAISSER !', ''),
(47441, 0, 'frFR', 'Ben c''est tout.', ''),
(47442, 0, 'frFR', 'Euh, ben on a quelques problèmes aux champs Fangeux, au nord-est d’ici. Le gardien Eau-Plate aurait besoin d’aide.', ''),
(47443, 0, 'frFR', 'Hum… On dirait qu’il y a des ennuis à Austrivage. Peut-être des insurgés worgens. Peut-être que vous pourriez aider ?', ''),
(47444, 0, 'frFR', 'Occupez-vous, allez faire une sieste par exemple. Je ne sais pas si j’ai du travail pour vous.', ''),
(47445, 0, 'frFR', 'Attendez, je crois que je viens de recevoir quelque chose. C''est ça, sur ce bout de papier, là. Vous devez aller au sud-est jusqu''à la mine de Veine-Azur et vous présenter au capitaine Keyton. Le sud-est, c''est par là. *Vous indiquez le sud-est*', ''),
(47446, 0, 'frFR', 'Rien.', ''),
(47447, 0, 'frFR', 'D’accord, merci. Contentez-vous de vous diriger au sud-est. Plutôt sud qu’est. Probablement au large de la côte.', ''),
(47715, 0, 'frFR', 'Je peux peut-être aider. Les Neferset sont-ils derrière tout ça ?', ''),
(47826, 0, 'frFR', 'Je suis prêt, Uchek !', ''),
(47842, 0, 'frFR', 'On vous accuse d’être un démon déguisé, Navarax… si c’est votre vrai nom !', ''),
(47923, 0, 'frFR', 'Vous devez mourir !', ''),
